-- ------------------------------------------------------------------
-- Source: supabase/sql/leads.sql
-- ------------------------------------------------------------------
-- Leads (marketing request access form)
--
-- IMPORTANT:
-- - Inserts should happen server-side using service_role (defense-in-depth).
-- - Browser roles should not be able to read or write leads directly.

create extension if not exists "pgcrypto";

-- Create the table if it doesn't exist (canonical schema)
create table if not exists public.leads (
  id uuid primary key default gen_random_uuid(),
  full_name text not null,
  email text not null,
  phone text not null,
  company text not null,
  company_size text,
  message text,
  requested_plan text not null default 'enterprise' check (requested_plan in ('starter','professional','enterprise')),
  status text not null check (status in ('new','contacted','qualified','rejected')) default 'new',
  handled_by uuid references public.profiles(id) on delete set null,
  handled_at timestamptz,
  decision_note text,
  created_at timestamptz not null default now()
);

-- Backward/forward compatibility:
-- If an older environment created `name` instead of `full_name`, migrate it safely.
do $$
begin
  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'leads'
      and column_name = 'name'
  ) and not exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'leads'
      and column_name = 'full_name'
  ) then
    alter table public.leads add column full_name text;
    update public.leads set full_name = name where full_name is null;
    alter table public.leads alter column full_name set not null;
  end if;
end $$;

-- Enterprise request workflow fields (for existing environments)
alter table public.leads add column if not exists requested_plan text;
alter table public.leads add column if not exists handled_by uuid references public.profiles(id) on delete set null;
alter table public.leads add column if not exists handled_at timestamptz;
alter table public.leads add column if not exists decision_note text;

update public.leads
set requested_plan = 'enterprise'
where requested_plan is null;

alter table public.leads alter column requested_plan set default 'enterprise';
alter table public.leads alter column requested_plan set not null;

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'leads_requested_plan_check'
      and conrelid = 'public.leads'::regclass
  ) then
    alter table public.leads
      add constraint leads_requested_plan_check
      check (requested_plan in ('starter', 'professional', 'enterprise'));
  end if;
end $$;

-- Prevent duplicate submissions by email (case-insensitive)
create unique index if not exists idx_leads_email_unique
  on public.leads (lower(email));

create index if not exists idx_leads_created_at
  on public.leads (created_at desc);

create index if not exists idx_leads_requested_plan_status_created_at
  on public.leads (requested_plan, status, created_at desc);

alter table public.leads enable row level security;

-- No policies: default deny for browser roles (service_role bypasses RLS).


-- ------------------------------------------------------------------
-- Source: supabase/sql/telegram_bot.sql
-- ------------------------------------------------------------------
-- Telegram bot support (webhook-only)
--
-- Adds:
-- - public.telegram_user_links: link Supabase profile <-> Telegram private chat_id
-- - public.telegram_connect_tokens: one-time tokens for /start deep link
--
-- Security:
-- - All privileged writes happen server-side using service_role (RLS bypass).
-- - Browser roles are denied write access by default (RLS enabled + deny policies).

-- 0) Ensure required extension for gen_random_uuid() exists (best-effort).
create extension if not exists "pgcrypto";

-- 1) User ↔ Telegram chat link
create table if not exists public.telegram_user_links (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  chat_id bigint not null unique,
  connected_at timestamptz not null default now(),
  last_seen_at timestamptz
);

alter table public.telegram_user_links enable row level security;

-- Select: user can read own link
do $$
begin
  if not exists (
    select 1
    from pg_policies
    where schemaname = 'public'
      and tablename = 'telegram_user_links'
      and policyname = 'telegram_user_links_select_own'
  ) then
    create policy telegram_user_links_select_own
      on public.telegram_user_links
      for select
      using (user_id = auth.uid());
  end if;
end $$;

-- Delete: user can unlink self
do $$
begin
  if not exists (
    select 1
    from pg_policies
    where schemaname = 'public'
      and tablename = 'telegram_user_links'
      and policyname = 'telegram_user_links_delete_own'
  ) then
    create policy telegram_user_links_delete_own
      on public.telegram_user_links
      for delete
      using (user_id = auth.uid());
  end if;
end $$;

-- Deny browser writes (service_role bypasses RLS)
do $$
begin
  if not exists (
    select 1
    from pg_policies
    where schemaname = 'public'
      and tablename = 'telegram_user_links'
      and policyname = 'telegram_user_links_deny_inserts'
  ) then
    create policy telegram_user_links_deny_inserts
      on public.telegram_user_links
      for insert
      with check (false);
  end if;

  if not exists (
    select 1
    from pg_policies
    where schemaname = 'public'
      and tablename = 'telegram_user_links'
      and policyname = 'telegram_user_links_deny_updates'
  ) then
    create policy telegram_user_links_deny_updates
      on public.telegram_user_links
      for update
      using (false)
      with check (false);
  end if;
end $$;

-- 2) One-time connect tokens (no browser access)
create table if not exists public.telegram_connect_tokens (
  token text primary key,
  user_id uuid not null references public.profiles(id) on delete cascade,
  expires_at timestamptz not null,
  used_at timestamptz,
  created_at timestamptz not null default now()
);

create index if not exists idx_telegram_connect_tokens_user_expires
  on public.telegram_connect_tokens(user_id, expires_at desc);

alter table public.telegram_connect_tokens enable row level security;

-- No policies needed: default deny for browser roles (service_role bypasses RLS).


