  where id = v_payment.id;

  select cp.scheduled_plan, cp.scheduled_plan_effective_at
    into v_existing_scheduled_plan, v_existing_scheduled_effective_at
  from public.company_plans cp
  where cp.company_id = v_payment.company_id
  for update;

  if found then
    v_clear_scheduled := v_existing_scheduled_plan is not null
      and (
        v_existing_scheduled_plan = v_payment.plan
        or (
          v_existing_scheduled_effective_at is not null
          and v_existing_scheduled_effective_at <= v_period_start
        )
      );

    update public.company_plans cp
      set current_plan = v_payment.plan,
          trial_expires_at = null,
          period_start = v_period_start,
          period_end = v_period_end,
          expires_at = v_period_end,
          robokassa_inv_id = p_inv_id::text,
          auto_renew = true,
          scheduled_plan = case when v_clear_scheduled then null else cp.scheduled_plan end,
          scheduled_plan_effective_at = case when v_clear_scheduled then null else cp.scheduled_plan_effective_at end,
          updated_at = now()
    where cp.company_id = v_payment.company_id;
  else
    insert into public.company_plans (
      company_id,
      current_plan,
      period_start,
      period_end,
      expires_at,
      robokassa_inv_id,
      auto_renew,
      scheduled_plan,
      scheduled_plan_effective_at
    )
    values (
      v_payment.company_id,
      v_payment.plan,
      v_period_start,
      v_period_end,
      v_period_end,
      p_inv_id::text,
      true,
      null,
      null
    )
    on conflict (company_id) do update
      set current_plan = excluded.current_plan,
          period_start = excluded.period_start,
          period_end = excluded.period_end,
          expires_at = excluded.expires_at,
          robokassa_inv_id = excluded.robokassa_inv_id,
          auto_renew = excluded.auto_renew,
          scheduled_plan = null,
          scheduled_plan_effective_at = null,
          updated_at = now();
  end if;

  if v_credits > 0 then
    insert into public.credit_ledger (
      company_id,
      delta,
      reason,
      reference_type,
      reference_id,
      notes
    )
    values (
      v_payment.company_id,
      v_credits,
      'grant',
      'plan_payment',
      v_payment.id,
      format('Plan payment inv_id=%s plan=%s', p_inv_id, v_payment.plan)
    )
    on conflict do nothing;
  end if;

  return query
  select
    v_payment.id,
    v_payment.company_id,
    v_payment.plan,
    v_credits,
    false;
end;
$$;


-- ------------------------------------------------------------------
-- Source: supabase/sql/handle_new_user_platform_admin_company_member_v1.sql
-- ------------------------------------------------------------------
-- ============================================================================
-- CANONICAL definition of public.handle_new_user()
-- This is the ONLY file that should define this function.
-- Other migration files (signup_trial_provisioning.sql, signup_trial_hardening.sql)
-- have had their function definitions removed and point here.
-- ============================================================================
--
-- Handle platform-admin user creation for existing company members without
-- triggering trial signup provisioning.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public, auth
as $$
declare
  v_email text;
  v_name text;
  v_company_name text;
  v_intended_plan text;
  v_company_id uuid;
  v_mode text;
  v_source text;
  v_company_id_text text;
  v_role text;
  v_company_exists boolean;
begin
  v_email := lower(trim(coalesce(new.email, '')));
  if v_email = '' then
    raise exception 'SIGNUP_EMAIL_REQUIRED';
  end if;

  v_name := nullif(trim(coalesce(new.raw_user_meta_data ->> 'name', '')), '');
  if v_name is null then
    v_name := split_part(v_email, '@', 1);
  end if;

  -- NOTE: Use raw_user_meta_data, NOT raw_app_meta_data. Supabase does not populate
  -- raw_app_meta_data during INSERT; it's set in a separate UPDATE. user_metadata
  -- is available in the INSERT trigger. See: https://github.com/supabase/auth/issues/975
  v_mode := lower(trim(coalesce(new.raw_user_meta_data ->> 'provisioning_mode', '')));
  v_source := lower(trim(coalesce(new.raw_user_meta_data ->> 'provisioning_source', '')));

  if v_mode = 'company_member' and v_source = 'platform_admin' then
    v_company_id_text := trim(coalesce(new.raw_user_meta_data ->> 'company_id', ''));
    if v_company_id_text = '' then
      raise exception 'INVALID_COMPANY_ID';
    end if;

    begin
      v_company_id := v_company_id_text::uuid;
    exception
      when others then
        raise exception 'INVALID_COMPANY_ID';
    end;

    v_role := lower(trim(coalesce(new.raw_user_meta_data ->> 'role', '')));
    if v_role not in ('admin', 'hr', 'recruiter') then
      raise exception 'INVALID_ROLE';
    end if;

    select exists(select 1 from public.companies c where c.id = v_company_id) into v_company_exists;
    if not v_company_exists then
      raise exception 'COMPANY_NOT_FOUND';
    end if;

    insert into public.profiles (id, email, name, company_id, role)
    values (new.id, v_email, v_name, v_company_id, v_role);

    raise log '[signup_provisioning] platform_admin success user_id=% email=% company_id=% role=%',
      new.id, v_email, v_company_id, v_role;

    return new;
  end if;

  -- Race-safe anti-abuse: reserve email in immutable trial registry.
  begin
    insert into public.trial_email_usage (email, first_user_id, first_used_at)
    values (v_email, new.id, now());
  exception
    when unique_violation then
      raise exception 'TRIAL_ALREADY_USED_FOR_EMAIL';
  end;

  v_company_name := nullif(trim(coalesce(new.raw_user_meta_data ->> 'company_name', '')), '');
  if v_company_name is null then
    v_company_name := 'Новая компания';
  end if;

  v_intended_plan := lower(trim(coalesce(new.raw_user_meta_data ->> 'intended_plan', '')));
  if v_intended_plan not in ('starter', 'professional') then
    v_intended_plan := 'starter';
  end if;

  insert into public.companies (name)
  values (v_company_name)
  returning id into v_company_id;

  insert into public.profiles (id, email, name, company_id, role)
  values (new.id, v_email, v_name, v_company_id, 'admin');

  update public.companies
    set created_by = new.id
  where id = v_company_id
    and created_by is null;

  update public.trial_email_usage
    set company_id = v_company_id
  where email = v_email;

  insert into public.company_plans (
    company_id,
    current_plan,
    trial_expires_at,
    intended_plan,
    period_start,
    period_end,
    auto_renew
  )
  values (
    v_company_id,
    'trial',
    now() + interval '7 days',
    v_intended_plan,
    now(),
    now() + interval '7 days',
    false
  )
  on conflict (company_id) do update
    set current_plan = excluded.current_plan,
        trial_expires_at = excluded.trial_expires_at,
        intended_plan = excluded.intended_plan,
        period_start = excluded.period_start,
        period_end = excluded.period_end,
        auto_renew = excluded.auto_renew,
        updated_at = now();

  insert into public.company_credits (company_id, balance, reserved, updated_at)
  values (v_company_id, 0, 0, now())
  on conflict (company_id) do nothing;

  insert into public.credit_ledger (
    company_id,
    delta,
    reason,
    reference_type,
    reference_id,
    notes,
    created_by
  )
  values (
    v_company_id,
    50,
    'grant',
    'trial_signup',
    new.id,
    'Trial signup grant (50 credits)',
    new.id
  )
  on conflict do nothing;

  insert into public.signup_provisioning_audit (
    user_id,
    email,
    company_id,
    intended_plan
  )
  values (
    new.id,
    v_email,
    v_company_id,
    v_intended_plan
  );

  raise log '[signup_provisioning] success user_id=% email=% company_id=% intended_plan=%',
    new.id, v_email, v_company_id, v_intended_plan;

  return new;
exception
  when others then
    raise log '[signup_provisioning] failed user_id=% email=% sqlstate=% error=%',
      new.id, coalesce(v_email, '<null>'), SQLSTATE, SQLERRM;
    raise;
end;
$$;

-- Ensure trigger is wired up (idempotent)
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();


-- ------------------------------------------------------------------
-- Source: supabase/sql/hh_sync_optimization_v1.sql
-- ------------------------------------------------------------------
-- HH sync optimization v1
--
-- Purpose:
-- - reduce steady-state DB traffic from worker HH sync
-- - make integration claiming safe for multiple workers
-- - persist HH source fingerprints to skip unchanged entities

do $$
begin
  if not exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'candidates'
      and column_name = 'hh_source_fingerprint'
  ) then
    alter table public.candidates add column hh_source_fingerprint text;
  end if;

  if not exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'vacancies'
      and column_name = 'hh_source_fingerprint'
  ) then
    alter table public.vacancies add column hh_source_fingerprint text;
  end if;

  if not exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'integrations_accounts'
      and column_name = 'sync_started_at'
  ) then
    alter table public.integrations_accounts add column sync_started_at timestamptz;
  end if;

  if not exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'integrations_accounts'
      and column_name = 'sync_lock_expires_at'
  ) then
    alter table public.integrations_accounts add column sync_lock_expires_at timestamptz;
  end if;

  if not exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'integrations_accounts'
      and column_name = 'last_sync_error'
  ) then
    alter table public.integrations_accounts add column last_sync_error text;
  end if;

  if not exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'integrations_accounts'
      and column_name = 'last_sync_error_at'
  ) then
    alter table public.integrations_accounts add column last_sync_error_at timestamptz;
  end if;
end $$;

create index if not exists idx_integrations_accounts_hh_due
  on public.integrations_accounts(provider, is_active, last_synced_at, sync_lock_expires_at)
  where provider = 'hh.ru' and is_active = true;

create or replace function public.claim_due_hh_integration(
  worker_id text,
  cutoff timestamptz,
  lease_seconds integer default 900
)
returns public.integrations_accounts
language plpgsql
security definer
set search_path = public
as $$
declare
  claimed public.integrations_accounts;
  ttl interval := make_interval(secs => greatest(30, coalesce(lease_seconds, 900)));
begin
  update public.integrations_accounts ia
  set
    sync_started_at = now(),
    sync_lock_expires_at = now() + ttl,
    updated_at = now()
  where ia.id = (
    select id
    from public.integrations_accounts
    where provider = 'hh.ru'
      and is_active = true
      and (last_synced_at is null or last_synced_at <= cutoff)
      and (sync_lock_expires_at is null or sync_lock_expires_at < now())
    order by
      coalesce(last_synced_at, to_timestamp(0)) asc,
      updated_at asc
    for update skip locked
    limit 1
  )
  returning * into claimed;

  return claimed;
end;
$$;


-- ------------------------------------------------------------------
-- Source: supabase/sql/signup_email_state_v1.sql
-- ------------------------------------------------------------------
-- Signup email state helper
--
-- Allows server-side signup flow to distinguish:
-- - no account
-- - existing confirmed account
-- - existing unconfirmed account

create or replace function public.get_signup_email_state(p_email text)
returns table (
  user_id uuid,
  email text,
  email_confirmed boolean
)
language sql
security definer
set search_path = public, auth
as $$
  select
    u.id as user_id,
    lower(trim(u.email)) as email,
    (u.email_confirmed_at is not null) as email_confirmed
  from auth.users u
  where lower(trim(coalesce(u.email, ''))) = lower(trim(coalesce(p_email, '')))
  order by u.created_at desc
  limit 1;
$$;

revoke all on function public.get_signup_email_state(text) from public;
revoke all on function public.get_signup_email_state(text) from anon;
revoke all on function public.get_signup_email_state(text) from authenticated;
grant execute on function public.get_signup_email_state(text) to service_role;


-- ------------------------------------------------------------------
-- Source: supabase/sql/candidate_create_idempotency_v1.sql
-- ------------------------------------------------------------------
create table if not exists public.api_idempotency_keys (
  key text primary key,
  operation text not null,
  user_id uuid not null references public.profiles(id) on delete cascade,
  company_id uuid not null references public.companies(id) on delete cascade,
  request_hash text not null,
  status text not null default 'in_progress' check (status in ('in_progress', 'completed')),
  response_status integer,
  response_body jsonb,
  candidate_id uuid references public.candidates(id) on delete set null,
  job_id uuid references public.jobs_ai(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  expires_at timestamptz not null default (now() + interval '1 day')
);

create index if not exists idx_api_idempotency_keys_company_user
  on public.api_idempotency_keys(company_id, user_id, created_at desc);

create index if not exists idx_api_idempotency_keys_expires_at
  on public.api_idempotency_keys(expires_at);

do $$
begin
  if not exists (
    select 1
    from pg_trigger
    where tgname = 'update_api_idempotency_keys_updated_at'
  ) then
    create trigger update_api_idempotency_keys_updated_at
      before update on public.api_idempotency_keys
      for each row execute function public.update_updated_at_column();
  end if;
end $$;

alter table public.api_idempotency_keys enable row level security;

do $$
begin
  if not exists (
    select 1
    from pg_policies
    where schemaname = 'public'
      and tablename = 'api_idempotency_keys'
      and policyname = 'api_idempotency_keys_deny_all'
  ) then
    create policy api_idempotency_keys_deny_all
      on public.api_idempotency_keys
      for all
      using (false)
      with check (false);
  end if;
end $$;

drop function if exists public.create_candidate_with_idempotency(
  text,
  text,
  uuid,
  uuid,
  text,
  uuid,
  text,
  text,
  text,
  text,
  timestamptz,
  text
);

create or replace function public.create_candidate_with_idempotency(
  p_key text,
  p_operation text,
  p_user_id uuid,
  p_company_id uuid,
  p_request_hash text,
  p_vacancy_id uuid,
  p_name text,
  p_position text,
  p_resume_text text,
  p_source text,
  p_applied_at timestamptz,
  p_mode text default 'enqueue'
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  inserted_count integer := 0;
  idem public.api_idempotency_keys;
  cand public.candidates;
  job public.jobs_ai;
  v_normalized_mode text := coalesce(p_mode, 'enqueue');
  v_response_status integer;
  v_response_body jsonb;
begin
  if v_normalized_mode not in ('enqueue', 'skip_ai_analysis', 'subscription_inactive') then
    raise exception 'invalid candidate create mode: %', v_normalized_mode;
  end if;

  insert into public.api_idempotency_keys (
    key,
    operation,
    user_id,
    company_id,
    request_hash,
    status
  ) values (
    p_key,
    p_operation,
    p_user_id,
    p_company_id,
    p_request_hash,
    'in_progress'
  )
  on conflict do nothing;

  get diagnostics inserted_count = row_count;

  if inserted_count = 0 then
    select *
    into idem
    from public.api_idempotency_keys
    where key = p_key
    for update;

    if not found then
      raise exception 'idempotency key lookup failed for key %', p_key;
    end if;

    if idem.operation <> p_operation
      or idem.user_id <> p_user_id
      or idem.company_id <> p_company_id
      or idem.request_hash <> p_request_hash then
      return jsonb_build_object(
        'responseStatus', 409,
        'responseBody', jsonb_build_object('error', 'IDEMPOTENCY_KEY_REUSED'),
        'candidateId', idem.candidate_id,
        'jobId', idem.job_id,
        'replayed', true
      );
    end if;

    if idem.status = 'completed'
      and idem.response_status is not null
      and idem.response_body is not null then
      return jsonb_build_object(
        'responseStatus', idem.response_status,
        'responseBody', idem.response_body,
        'candidateId', idem.candidate_id,
        'jobId', idem.job_id,
        'replayed', true
      );
    end if;

    return jsonb_build_object(
      'responseStatus', 409,
      'responseBody', jsonb_build_object('error', 'IDEMPOTENCY_REQUEST_IN_PROGRESS'),
      'candidateId', idem.candidate_id,
      'jobId', idem.job_id,
      'replayed', true
    );
  end if;

  insert into public.candidates (
    name,
    position,
    vacancy_id,
    created_by,
    resume_text,
    source,
    status,
    applied_at
  ) values (
    p_name,
    p_position,
    p_vacancy_id,
    p_user_id,
    p_resume_text,
    p_source,
    'new',
    p_applied_at
  )
  returning * into cand;

  if v_normalized_mode = 'enqueue' then
    select *
    into job
    from public.enqueue_ai_job_with_credit_reserve(
      p_company_id,
      cand.id,
      p_user_id,
      1
    );

    v_response_status := 200;
    v_response_body := jsonb_build_object(
      'candidateId', cand.id,
      'jobId', job.id
    );
  elsif v_normalized_mode = 'skip_ai_analysis' then
    v_response_status := 200;
    v_response_body := jsonb_build_object(
      'candidateId', cand.id,
      'jobId', null
    );
  else
    v_response_status := 402;
    v_response_body := jsonb_build_object(
      'error', 'SUBSCRIPTION_INACTIVE',
      'candidateId', cand.id
    );
  end if;

  update public.api_idempotency_keys
    set status = 'completed',
        response_status = v_response_status,
        response_body = v_response_body,
        candidate_id = cand.id,
        job_id = job.id,
        updated_at = now()
  where key = p_key;

  return jsonb_build_object(
    'responseStatus', v_response_status,
    'responseBody', v_response_body,
    'candidateId', cand.id,
    'jobId', job.id,
    'replayed', false
  );
exception
  when others then
    delete from public.api_idempotency_keys
    where key = p_key
      and status = 'in_progress'
      and response_status is null;
    raise;
end;
$$;


-- ------------------------------------------------------------------
-- Source: supabase/sql/verification_email_resend_limit_v1.sql
-- ------------------------------------------------------------------
-- Verification email resend hardening
--
-- Goals:
-- - Keep resend cooldown and hourly resend limit on the server
-- - Share the limit across tabs, windows, incognito sessions, and app instances
-- - Allow only service role to consume the limiter

create table if not exists public.verification_email_resend_limits (
  email text primary key,
  last_resend_at timestamptz,
  resend_window_started_at timestamptz not null,
  resend_count_in_window integer not null default 0 check (resend_count_in_window >= 0),
  updated_at timestamptz not null default now()
);

alter table public.verification_email_resend_limits enable row level security;

do $$
begin
  if not exists (
    select 1
    from pg_policies
    where schemaname = 'public'
      and tablename = 'verification_email_resend_limits'
      and policyname = 'verification_email_resend_limits_deny_select'
  ) then
    create policy verification_email_resend_limits_deny_select
      on public.verification_email_resend_limits
      for select
      using (false);
  end if;

  if not exists (
    select 1
    from pg_policies
    where schemaname = 'public'
      and tablename = 'verification_email_resend_limits'
      and policyname = 'verification_email_resend_limits_deny_insert'
  ) then
    create policy verification_email_resend_limits_deny_insert
      on public.verification_email_resend_limits
      for insert
      with check (false);
  end if;

  if not exists (
    select 1
    from pg_policies
    where schemaname = 'public'
      and tablename = 'verification_email_resend_limits'
      and policyname = 'verification_email_resend_limits_deny_update'
  ) then
    create policy verification_email_resend_limits_deny_update
      on public.verification_email_resend_limits
      for update
      using (false)
      with check (false);
  end if;

  if not exists (
    select 1
    from pg_policies
    where schemaname = 'public'
      and tablename = 'verification_email_resend_limits'
      and policyname = 'verification_email_resend_limits_deny_delete'
  ) then
    create policy verification_email_resend_limits_deny_delete
      on public.verification_email_resend_limits
      for delete
      using (false);
  end if;
end $$;

create index if not exists idx_verification_email_resend_limits_updated_at
  on public.verification_email_resend_limits(updated_at desc);

create or replace function public.consume_verification_email_resend_limit(
  p_email text,
  p_cooldown_seconds integer default 60,
  p_window_seconds integer default 3600,
  p_max_resends integer default 5,
  p_now timestamptz default now()
)
returns table (
  allowed boolean,
  reason text,
  cooldown_left_seconds integer,
  retry_after_seconds integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  normalized_email text := lower(trim(coalesce(p_email, '')));
  effective_now timestamptz := coalesce(p_now, now());
  current_record public.verification_email_resend_limits%rowtype;
  effective_window_started_at timestamptz;
  effective_count integer;
  cooldown_left integer;
  retry_after integer;
begin
  if normalized_email = '' then
    raise exception 'p_email is required';
  end if;

  if coalesce(p_cooldown_seconds, 0) < 0 or coalesce(p_window_seconds, 0) <= 0 or coalesce(p_max_resends, 0) <= 0 then
    raise exception 'Invalid verification resend limiter parameters';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(normalized_email, 0));

  select *
  into current_record
  from public.verification_email_resend_limits
  where email = normalized_email
  for update;

  if not found then
    insert into public.verification_email_resend_limits (
      email,
      last_resend_at,
      resend_window_started_at,
      resend_count_in_window,
      updated_at
    )
    values (
      normalized_email,
      effective_now,
      effective_now,
      1,
      now()
    );

    return query
    select true, null::text, null::integer, null::integer;
    return;
  end if;

  effective_window_started_at := case
    when extract(epoch from (effective_now - current_record.resend_window_started_at)) >= p_window_seconds then effective_now
    else current_record.resend_window_started_at
  end;

  effective_count := case
    when effective_window_started_at = effective_now then 0
    else current_record.resend_count_in_window
  end;

  if current_record.last_resend_at is not null then
    cooldown_left := ceil(
      p_cooldown_seconds - extract(epoch from (effective_now - current_record.last_resend_at))
    );

    if cooldown_left > 0 then
      return query
      select false, 'cooldown'::text, cooldown_left, null::integer;
      return;
    end if;
  end if;

  if effective_count >= p_max_resends then
    retry_after := greatest(
      1,
      ceil(p_window_seconds - extract(epoch from (effective_now - effective_window_started_at)))
    );

    update public.verification_email_resend_limits
    set
      resend_window_started_at = effective_window_started_at,
      resend_count_in_window = effective_count,
      updated_at = now()
    where email = normalized_email;

    return query
    select false, 'rate_limit'::text, null::integer, retry_after;
    return;
  end if;

  update public.verification_email_resend_limits
  set
    last_resend_at = effective_now,
    resend_window_started_at = effective_window_started_at,
    resend_count_in_window = effective_count + 1,
    updated_at = now()
  where email = normalized_email;

  return query
  select true, null::text, null::integer, null::integer;
end;
$$;

revoke all on table public.verification_email_resend_limits from public;
revoke all on table public.verification_email_resend_limits from anon;
revoke all on table public.verification_email_resend_limits from authenticated;
grant all on table public.verification_email_resend_limits to service_role;

revoke all on function public.consume_verification_email_resend_limit(text, integer, integer, integer, timestamptz) from public;
revoke all on function public.consume_verification_email_resend_limit(text, integer, integer, integer, timestamptz) from anon;
revoke all on function public.consume_verification_email_resend_limit(text, integer, integer, integer, timestamptz) from authenticated;
grant execute on function public.consume_verification_email_resend_limit(text, integer, integer, integer, timestamptz) to service_role;


-- ------------------------------------------------------------------
-- Source: supabase/sql/billing_paid_scheduled_downgrade_v1.sql
-- ------------------------------------------------------------------
-- Billing paid scheduled downgrade v1
--
-- Goals:
-- - Allow a user with auto_renew=false to pay for a downgrade now.
-- - Keep the current higher plan active until the already-paid period ends.
-- - Activate the paid lower plan later via cron without charging again.

alter table public.payments
  add column if not exists activate_auto_renew boolean not null default true;

alter table public.company_plans
  add column if not exists scheduled_payment_id uuid null;

do $$
begin
  if not exists (
    select 1
    from pg_constraint c
    join pg_class t on t.oid = c.conrelid
    join pg_namespace n on n.oid = t.relnamespace
    where n.nspname = 'public'
      and t.relname = 'company_plans'
      and c.conname = 'company_plans_scheduled_payment_id_fkey'
  ) then
    alter table public.company_plans
      add constraint company_plans_scheduled_payment_id_fkey
      foreign key (scheduled_payment_id)
      references public.payments(id)
      on delete set null;
  end if;
end $$;

do $$
begin
  if not exists (
    select 1
    from pg_constraint c
    join pg_class t on t.oid = c.conrelid
    join pg_namespace n on n.oid = t.relnamespace
    where n.nspname = 'public'
      and t.relname = 'company_plans'
      and c.conname = 'company_plans_scheduled_payment_consistency_check'
  ) then
    alter table public.company_plans
      add constraint company_plans_scheduled_payment_consistency_check
      check (
        scheduled_payment_id is null
        or (scheduled_plan is not null and scheduled_plan_effective_at is not null)
      );
  end if;
end $$;

create index if not exists idx_company_plans_scheduled_payment_due
  on public.company_plans (scheduled_plan_effective_at)
  where scheduled_payment_id is not null;

create or replace function public.finalize_robokassa_payment(
  p_inv_id integer,
  p_provider_id text,
  p_completed_at timestamptz default now()
)
returns table (
  payment_id uuid,
  company_id uuid,
  plan text,
  credits_granted integer,
  already_completed boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_payment public.payments;
  v_company_plan public.company_plans;
  v_completed_at timestamptz;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_credits integer;
  v_existing_scheduled_plan text;
  v_existing_scheduled_effective_at timestamptz;
  v_clear_scheduled boolean := false;
  v_company_plan_found boolean := false;
  v_defer_plan_activation boolean := false;
  v_granted_credits integer := 0;
begin
  select *
    into v_payment
  from public.payments
  where inv_id = p_inv_id
  for update;

  if not found then
    raise exception 'PAYMENT_NOT_FOUND';
  end if;

  if v_payment.status = 'completed' then
    return query
    select
      v_payment.id,
      v_payment.company_id,
      v_payment.plan,
      coalesce(v_payment.credits_granted, 0),
      true;
    return;
  end if;

  if v_payment.status <> 'pending' then
    raise exception 'PAYMENT_NOT_PENDING';
  end if;

  v_completed_at := coalesce(p_completed_at, now());
  v_credits := case
    when v_payment.plan = 'starter' then 300
    when v_payment.plan = 'professional' then 1200
    else 0
  end;

  v_period_start := coalesce(v_payment.period_start, now());
  v_period_end := coalesce(v_payment.period_end, v_period_start + interval '1 month');

  select *
    into v_company_plan
  from public.company_plans cp
  where cp.company_id = v_payment.company_id
  for update;
  v_company_plan_found := found;

  if v_company_plan_found then
    v_defer_plan_activation := v_company_plan.current_plan = 'professional'
      and v_payment.plan = 'starter'
      and coalesce(v_company_plan.auto_renew, false) = false
      and v_company_plan.period_end is not null
      and v_company_plan.period_end >= v_completed_at
      and v_period_start >= v_company_plan.period_end
      and v_period_start > v_completed_at;
  end if;

  v_granted_credits := case when v_defer_plan_activation then 0 else v_credits end;

  update public.payments
    set status = 'completed',
        completed_at = v_completed_at,
        provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
        credits_granted = coalesce(v_payment.credits_granted, v_granted_credits),
        period_start = v_period_start,
        period_end = v_period_end,
        failed_at = null,
        fail_reason = null
  where id = v_payment.id;

  if v_defer_plan_activation then
    update public.company_plans cp
      set scheduled_plan = v_payment.plan,
          scheduled_plan_effective_at = v_period_start,
          scheduled_payment_id = v_payment.id,
          updated_at = now()
    where cp.company_id = v_payment.company_id;

    return query
    select
      v_payment.id,
      v_payment.company_id,
      v_payment.plan,
      0,
      false;
    return;
  end if;

  if v_company_plan_found then
    v_existing_scheduled_plan := v_company_plan.scheduled_plan;
    v_existing_scheduled_effective_at := v_company_plan.scheduled_plan_effective_at;
    v_clear_scheduled := v_existing_scheduled_plan is not null
      and (
        v_existing_scheduled_plan = v_payment.plan
        or (
          v_existing_scheduled_effective_at is not null
          and v_existing_scheduled_effective_at <= v_period_start
        )
      );

    update public.company_plans cp
      set current_plan = v_payment.plan,
          trial_expires_at = null,
          period_start = v_period_start,
          period_end = v_period_end,
          expires_at = v_period_end,
          robokassa_inv_id = p_inv_id::text,
          auto_renew = coalesce(v_payment.activate_auto_renew, true),
          scheduled_plan = case when v_clear_scheduled then null else cp.scheduled_plan end,
          scheduled_plan_effective_at = case when v_clear_scheduled then null else cp.scheduled_plan_effective_at end,
          scheduled_payment_id = case when v_clear_scheduled then null else cp.scheduled_payment_id end,
          updated_at = now()
    where cp.company_id = v_payment.company_id;
  else
    insert into public.company_plans (
      company_id,
      current_plan,
      period_start,
      period_end,
      expires_at,
      robokassa_inv_id,
      auto_renew,
      scheduled_plan,
      scheduled_plan_effective_at,
      scheduled_payment_id
    )
    values (
      v_payment.company_id,
      v_payment.plan,
      v_period_start,
      v_period_end,
      v_period_end,
      p_inv_id::text,
      coalesce(v_payment.activate_auto_renew, true),
      null,
      null,
      null
    )
    on conflict (company_id) do update
      set current_plan = excluded.current_plan,
          period_start = excluded.period_start,
          period_end = excluded.period_end,
          expires_at = excluded.expires_at,
          robokassa_inv_id = excluded.robokassa_inv_id,
          auto_renew = excluded.auto_renew,
          scheduled_plan = null,
          scheduled_plan_effective_at = null,
          scheduled_payment_id = null,
          updated_at = now();
  end if;

  if v_credits > 0 then
    insert into public.credit_ledger (
      company_id,
      delta,
      reason,
      reference_type,
      reference_id,
      notes
    )
    values (
      v_payment.company_id,
      v_credits,
      'grant',
      'plan_payment',
      v_payment.id,
      format('Plan payment inv_id=%s plan=%s', p_inv_id, v_payment.plan)
    )
    on conflict do nothing;
  end if;

  return query
  select
    v_payment.id,
    v_payment.company_id,
    v_payment.plan,
    v_credits,
    false;
end;
$$;

create or replace function public.activate_due_scheduled_plan_payments(
  p_now timestamptz default now()
)
returns table (
  company_id uuid,
  payment_id uuid,
  plan text,
  credits_granted integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_row record;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_credits integer;
begin
  for v_row in
    select
      cp.company_id,
      cp.scheduled_plan,
      cp.scheduled_plan_effective_at,
      p.id as payment_id,
      p.plan as payment_plan,
      p.inv_id,
      p.period_start,
      p.period_end,
      p.activate_auto_renew
    from public.company_plans cp
    join public.payments p on p.id = cp.scheduled_payment_id
    where cp.scheduled_payment_id is not null
      and cp.scheduled_plan is not null
      and cp.scheduled_plan_effective_at is not null
      and cp.scheduled_plan_effective_at <= p_now
      and p.status = 'completed'
      and p.plan = cp.scheduled_plan
    for update of cp, p
  loop
    v_period_start := coalesce(v_row.period_start, v_row.scheduled_plan_effective_at);
    v_period_end := coalesce(v_row.period_end, v_period_start + interval '1 month');
    v_credits := case
      when v_row.payment_plan = 'starter' then 300
      when v_row.payment_plan = 'professional' then 1200
      else 0
    end;

    update public.company_plans cp
      set current_plan = v_row.payment_plan,
          trial_expires_at = null,
          period_start = v_period_start,
          period_end = v_period_end,
          expires_at = v_period_end,
          robokassa_inv_id = v_row.inv_id::text,
          auto_renew = coalesce(v_row.activate_auto_renew, true),
          scheduled_plan = null,
          scheduled_plan_effective_at = null,
          scheduled_payment_id = null,
          updated_at = now()
    where cp.company_id = v_row.company_id;

    update public.payments p
      set credits_granted = v_credits
    where p.id = v_row.payment_id
      and coalesce(p.credits_granted, 0) = 0;

    if v_credits > 0 then
      insert into public.credit_ledger (
        company_id,
        delta,
        reason,
        reference_type,
        reference_id,
        notes
      )
      values (
        v_row.company_id,
        v_credits,
        'grant',
        'plan_payment',
        v_row.payment_id,
        format('Plan payment inv_id=%s plan=%s', v_row.inv_id, v_row.payment_plan)
      )
      on conflict do nothing;
    end if;

    return query
    select
      v_row.company_id,
      v_row.payment_id,
      v_row.payment_plan,
      v_credits;
  end loop;
end;
$$;


-- ------------------------------------------------------------------
-- Source: supabase/sql/billing_paid_scheduled_downgrade_hardening_v1.sql
-- ------------------------------------------------------------------
-- Billing paid scheduled downgrade hardening v1
--
-- Goals:
-- - Scope due scheduled payment activation to a single company when needed.
-- - Prevent accidental paid schedule overwrites at the database layer.

create or replace function public.activate_due_scheduled_plan_payments(
  p_now timestamptz default now(),
  p_company_id uuid default null
)
returns table (
  company_id uuid,
  payment_id uuid,
  plan text,
  credits_granted integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_row record;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_credits integer;
begin
  for v_row in
    select
      cp.company_id,
      cp.scheduled_plan,
      cp.scheduled_plan_effective_at,
      p.id as payment_id,
      p.plan as payment_plan,
      p.inv_id,
      p.period_start,
      p.period_end,
      p.activate_auto_renew
    from public.company_plans cp
    join public.payments p on p.id = cp.scheduled_payment_id
    where cp.scheduled_payment_id is not null
      and (p_company_id is null or cp.company_id = p_company_id)
      and cp.scheduled_plan is not null
      and cp.scheduled_plan_effective_at is not null
      and cp.scheduled_plan_effective_at <= p_now
      and p.status = 'completed'
      and p.plan = cp.scheduled_plan
    for update of cp, p
  loop
    v_period_start := coalesce(v_row.period_start, v_row.scheduled_plan_effective_at);
    v_period_end := coalesce(v_row.period_end, v_period_start + interval '1 month');
    v_credits := case
      when v_row.payment_plan = 'starter' then 500
      when v_row.payment_plan = 'professional' then 2000
      else 0
    end;

    update public.company_plans cp
      set current_plan = v_row.payment_plan,
          trial_expires_at = null,
          period_start = v_period_start,
          period_end = v_period_end,
          expires_at = v_period_end,
          robokassa_inv_id = v_row.inv_id::text,
          auto_renew = coalesce(v_row.activate_auto_renew, true),
          scheduled_plan = null,
          scheduled_plan_effective_at = null,
          scheduled_payment_id = null,
          updated_at = now()
    where cp.company_id = v_row.company_id;

    update public.payments p
      set credits_granted = v_credits
    where p.id = v_row.payment_id
      and coalesce(p.credits_granted, 0) = 0;

    if v_credits > 0 then
      insert into public.credit_ledger (
        company_id,
        delta,
        reason,
        reference_type,
        reference_id,
        notes
      )
      values (
        v_row.company_id,
        v_credits,
        'grant',
        'plan_payment',
        v_row.payment_id,
        format('Plan payment inv_id=%s plan=%s', v_row.inv_id, v_row.payment_plan)
      )
      on conflict do nothing;
    end if;

    return query
    select
      v_row.company_id,
      v_row.payment_id,
      v_row.payment_plan,
      v_credits;
  end loop;
end;
$$;

create or replace function public.prevent_paid_schedule_overwrite()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if old.scheduled_payment_id is not null
    and old.scheduled_payment_id is distinct from new.scheduled_payment_id
    and not (
      new.scheduled_payment_id is null
      and new.scheduled_plan is null
      and new.scheduled_plan_effective_at is null
      and new.current_plan = old.scheduled_plan
    )
    and (
      new.scheduled_payment_id is null
      or old.scheduled_plan is distinct from new.scheduled_plan
      or old.scheduled_plan_effective_at is distinct from new.scheduled_plan_effective_at
    )
  then
    raise exception 'PAID_SCHEDULE_CANNOT_OVERWRITE';
  end if;

  return new;
end;
$$;

drop trigger if exists company_plans_prevent_paid_schedule_overwrite on public.company_plans;
create trigger company_plans_prevent_paid_schedule_overwrite
  before update on public.company_plans
  for each row
  execute function public.prevent_paid_schedule_overwrite();


-- ------------------------------------------------------------------
-- Source: supabase/sql/billing_paid_scheduled_downgrade_production_hardening_v1.sql
-- ------------------------------------------------------------------
-- Billing paid scheduled downgrade production hardening v1
--
-- Goals:
-- - Prevent duplicate active self-service payments for the same future period.
-- - Treat late payment of a future downgrade invoice as a new period from payment completion.
-- - Block any paid scheduled downgrade mutation except normal activation.

create unique index if not exists idx_payments_self_service_active_period_once
  on public.payments (company_id, plan, period_start)
  where status in ('pending', 'completed')
    and is_recurring = false
    and period_start is not null;

create or replace function public.finalize_robokassa_payment(
  p_inv_id integer,
  p_provider_id text,
  p_completed_at timestamptz default now()
)
returns table (
  payment_id uuid,
  company_id uuid,
  plan text,
  credits_granted integer,
  already_completed boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_payment public.payments;
  v_company_plan public.company_plans;
  v_completed_at timestamptz;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_credits integer;
  v_existing_scheduled_plan text;
  v_existing_scheduled_effective_at timestamptz;
  v_clear_scheduled boolean := false;
  v_company_plan_found boolean := false;
  v_is_professional_to_starter_without_autorenew boolean := false;
  v_defer_plan_activation boolean := false;
  v_granted_credits integer := 0;
begin
  select *
    into v_payment
  from public.payments
  where inv_id = p_inv_id
  for update;

  if not found then
    raise exception 'PAYMENT_NOT_FOUND';
  end if;

  if v_payment.status = 'completed' then
    return query
    select
      v_payment.id,
      v_payment.company_id,
      v_payment.plan,
      coalesce(v_payment.credits_granted, 0),
      true;
    return;
  end if;

  if v_payment.status <> 'pending' then
    raise exception 'PAYMENT_NOT_PENDING';
  end if;

  v_completed_at := coalesce(p_completed_at, now());
  v_credits := case
    when v_payment.plan = 'starter' then 300
    when v_payment.plan = 'professional' then 1200
    else 0
  end;

  v_period_start := coalesce(v_payment.period_start, now());
  v_period_end := coalesce(v_payment.period_end, v_period_start + interval '1 month');

  select *
    into v_company_plan
  from public.company_plans cp
  where cp.company_id = v_payment.company_id
  for update;
  v_company_plan_found := found;

  if v_company_plan_found then
    v_is_professional_to_starter_without_autorenew := v_company_plan.current_plan = 'professional'
      and v_payment.plan = 'starter'
      and coalesce(v_company_plan.auto_renew, false) = false
      and v_company_plan.period_end is not null
      and v_period_start >= v_company_plan.period_end;

    if v_is_professional_to_starter_without_autorenew
      and v_company_plan.period_end >= v_completed_at
      and v_period_start > v_completed_at
    then
      v_defer_plan_activation := true;
    elsif v_is_professional_to_starter_without_autorenew
      and v_completed_at >= v_company_plan.period_end
    then
      -- The invoice was paid after the already-paid Professional period ended.
      -- Do not sell a period that has already partly or fully passed.
      v_period_start := v_completed_at;
      v_period_end := v_period_start + interval '1 month';
    end if;
  end if;

  if v_defer_plan_activation
    and v_company_plan.scheduled_payment_id is not null
    and v_company_plan.scheduled_payment_id <> v_payment.id
  then
    raise exception 'PAID_SCHEDULE_EXISTS';
  end if;

  v_granted_credits := case when v_defer_plan_activation then 0 else v_credits end;

  update public.payments
    set status = 'completed',
        completed_at = v_completed_at,
        provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
        credits_granted = coalesce(v_payment.credits_granted, v_granted_credits),
        period_start = v_period_start,
        period_end = v_period_end,
        failed_at = null,
        fail_reason = null
  where id = v_payment.id;

  if v_defer_plan_activation then
    update public.company_plans cp
      set scheduled_plan = v_payment.plan,
          scheduled_plan_effective_at = v_period_start,
          scheduled_payment_id = v_payment.id,
          updated_at = now()
    where cp.company_id = v_payment.company_id;

    return query
    select
      v_payment.id,
      v_payment.company_id,
      v_payment.plan,
      0,
      false;
    return;
  end if;

  if v_company_plan_found then
    v_existing_scheduled_plan := v_company_plan.scheduled_plan;
    v_existing_scheduled_effective_at := v_company_plan.scheduled_plan_effective_at;
    v_clear_scheduled := v_existing_scheduled_plan is not null
      and (
        v_existing_scheduled_plan = v_payment.plan
        or (
          v_existing_scheduled_effective_at is not null
          and v_existing_scheduled_effective_at <= v_period_start
        )
      );

    update public.company_plans cp
      set current_plan = v_payment.plan,
          trial_expires_at = null,
          period_start = v_period_start,
          period_end = v_period_end,
          expires_at = v_period_end,
          robokassa_inv_id = p_inv_id::text,
          auto_renew = coalesce(v_payment.activate_auto_renew, true),
          scheduled_plan = case when v_clear_scheduled then null else cp.scheduled_plan end,
          scheduled_plan_effective_at = case when v_clear_scheduled then null else cp.scheduled_plan_effective_at end,
          scheduled_payment_id = case when v_clear_scheduled then null else cp.scheduled_payment_id end,
          updated_at = now()
    where cp.company_id = v_payment.company_id;
  else
    insert into public.company_plans (
      company_id,
      current_plan,
      period_start,
      period_end,
      expires_at,
      robokassa_inv_id,
      auto_renew,
      scheduled_plan,
      scheduled_plan_effective_at,
      scheduled_payment_id
    )
    values (
      v_payment.company_id,
      v_payment.plan,
      v_period_start,
      v_period_end,
      v_period_end,
      p_inv_id::text,
      coalesce(v_payment.activate_auto_renew, true),
      null,
      null,
      null
    )
    on conflict (company_id) do update
      set current_plan = excluded.current_plan,
          period_start = excluded.period_start,
          period_end = excluded.period_end,
          expires_at = excluded.expires_at,
          robokassa_inv_id = excluded.robokassa_inv_id,
          auto_renew = excluded.auto_renew,
          scheduled_plan = null,
          scheduled_plan_effective_at = null,
          scheduled_payment_id = null,
          updated_at = now();
  end if;

  if v_credits > 0 then
    insert into public.credit_ledger (
      company_id,
      delta,
      reason,
      reference_type,
      reference_id,
      notes
    )
    values (
      v_payment.company_id,
      v_credits,
      'grant',
      'plan_payment',
      v_payment.id,
      format('Plan payment inv_id=%s plan=%s', p_inv_id, v_payment.plan)
    )
    on conflict do nothing;
  end if;

  return query
  select
    v_payment.id,
    v_payment.company_id,
    v_payment.plan,
    v_credits,
    false;
end;
$$;

create or replace function public.prevent_paid_schedule_overwrite()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if old.scheduled_payment_id is not null
    and not (
      new.scheduled_payment_id is null
      and new.scheduled_plan is null
      and new.scheduled_plan_effective_at is null
      and new.current_plan = old.scheduled_plan
    )
    and (
      old.scheduled_payment_id is distinct from new.scheduled_payment_id
      or old.scheduled_plan is distinct from new.scheduled_plan
      or old.scheduled_plan_effective_at is distinct from new.scheduled_plan_effective_at
    )
  then
    raise exception 'PAID_SCHEDULE_CANNOT_OVERWRITE';
  end if;

  return new;
end;
$$;

drop trigger if exists company_plans_prevent_paid_schedule_overwrite on public.company_plans;
create trigger company_plans_prevent_paid_schedule_overwrite
  before update on public.company_plans
  for each row
  execute function public.prevent_paid_schedule_overwrite();


-- ------------------------------------------------------------------
-- Source: supabase/sql/billing_paid_scheduled_downgrade_review_fixes_v1.sql
-- ------------------------------------------------------------------
-- Billing paid scheduled downgrade review fixes v1
--
-- Goals:
-- - Persist immutable checkout intent for paid scheduled downgrades.
-- - Finalize Robokassa callbacks from payment intent, not mutable company state.
-- - Keep current auto-renew and future scheduled-payment auto-renew in one DB transaction.
-- - Put stale captured payments into manual review without changing the active plan.

alter table public.payments
  add column if not exists scheduled_change_kind text null,
  add column if not exists scheduled_source_plan text null,
  add column if not exists scheduled_source_period_end timestamptz null,
  add column if not exists scheduled_activation_at timestamptz null;

alter table public.payments
  drop constraint if exists payments_status_check;

alter table public.payments
  add constraint payments_status_check
  check (status in ('pending', 'completed', 'failed', 'refunded', 'requires_review'));

do $$
begin
  if not exists (
    select 1
    from pg_constraint c
    join pg_class t on t.oid = c.conrelid
    join pg_namespace n on n.oid = t.relnamespace
    where n.nspname = 'public'
      and t.relname = 'payments'
      and c.conname = 'payments_scheduled_change_kind_check'
  ) then
    alter table public.payments
      add constraint payments_scheduled_change_kind_check
      check (scheduled_change_kind is null or scheduled_change_kind in ('paid_downgrade'));
  end if;

  if not exists (
    select 1
    from pg_constraint c
    join pg_class t on t.oid = c.conrelid
    join pg_namespace n on n.oid = t.relnamespace
    where n.nspname = 'public'
      and t.relname = 'payments'
      and c.conname = 'payments_scheduled_source_plan_check'
  ) then
    alter table public.payments
      add constraint payments_scheduled_source_plan_check
      check (scheduled_source_plan is null or scheduled_source_plan in ('starter', 'professional', 'enterprise'));
  end if;

  if not exists (
    select 1
    from pg_constraint c
    join pg_class t on t.oid = c.conrelid
    join pg_namespace n on n.oid = t.relnamespace
    where n.nspname = 'public'
      and t.relname = 'payments'
      and c.conname = 'payments_scheduled_change_consistency_check'
  ) then
    alter table public.payments
      add constraint payments_scheduled_change_consistency_check
      check (
        (
          scheduled_change_kind is null
          and scheduled_source_plan is null
          and scheduled_source_period_end is null
          and scheduled_activation_at is null
        )
        or (
          scheduled_change_kind = 'paid_downgrade'
          and scheduled_source_plan is not null
          and scheduled_source_period_end is not null
          and scheduled_activation_at is not null
        )
      );
  end if;
end $$;

drop index if exists public.idx_payments_self_service_active_period_once;
create unique index if not exists idx_payments_self_service_active_period_once
  on public.payments (company_id, plan, period_start)
  where status in ('pending', 'completed', 'requires_review')
    and is_recurring = false
    and period_start is not null;

create or replace function public.set_company_plan_auto_renew(
  p_company_id uuid,
  p_enabled boolean
)
returns table (
  company_id uuid,
  current_plan text,
  auto_renew boolean,
  scheduled_plan text,
  scheduled_plan_effective_at timestamptz,
  scheduled_payment_id uuid
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_plan public.company_plans;
begin
  select *
    into v_plan
  from public.company_plans cp
  where cp.company_id = p_company_id
  for update;

  if not found then
    raise exception 'COMPANY_PLAN_NOT_FOUND';
  end if;

  if p_enabled then
    update public.company_plans cp
      set auto_renew = true,
          updated_at = now()
    where cp.company_id = p_company_id;
  else
    update public.company_plans cp
      set auto_renew = false,
          scheduled_plan = case when v_plan.scheduled_payment_id is null then null else cp.scheduled_plan end,
          scheduled_plan_effective_at = case when v_plan.scheduled_payment_id is null then null else cp.scheduled_plan_effective_at end,
          scheduled_payment_id = case when v_plan.scheduled_payment_id is null then null else cp.scheduled_payment_id end,
          updated_at = now()
    where cp.company_id = p_company_id;
  end if;

  update public.payments p
    set activate_auto_renew = p_enabled
  where p.company_id = p_company_id
    and p.is_recurring = false
    and p.scheduled_change_kind = 'paid_downgrade'
    and (
      p.status = 'pending'
      or p.id = v_plan.scheduled_payment_id
    );

  return query
  select
    cp.company_id,
    cp.current_plan,
    cp.auto_renew,
    cp.scheduled_plan,
    cp.scheduled_plan_effective_at,
    cp.scheduled_payment_id
  from public.company_plans cp
  where cp.company_id = p_company_id;
end;
$$;

revoke all on function public.set_company_plan_auto_renew(uuid, boolean) from public, anon, authenticated;
grant execute on function public.set_company_plan_auto_renew(uuid, boolean) to service_role;

create or replace function public.finalize_robokassa_payment(
  p_inv_id integer,
  p_provider_id text,
  p_completed_at timestamptz default now()
)
returns table (
  payment_id uuid,
  company_id uuid,
  plan text,
  credits_granted integer,
  already_completed boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_payment public.payments;
  v_company_plan public.company_plans;
  v_completed_at timestamptz;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_credits integer;
  v_existing_scheduled_plan text;
  v_existing_scheduled_effective_at timestamptz;
  v_clear_scheduled boolean := false;
  v_company_plan_found boolean := false;
  v_is_paid_scheduled_downgrade boolean := false;
  v_defer_plan_activation boolean := false;
  v_granted_credits integer := 0;
begin
  select *
    into v_payment
  from public.payments
  where inv_id = p_inv_id
  for update;

  if not found then
    raise exception 'PAYMENT_NOT_FOUND';
  end if;

  if v_payment.status = 'completed' then
    return query
    select
      v_payment.id,
      v_payment.company_id,
      v_payment.plan,
      coalesce(v_payment.credits_granted, 0),
      true;
    return;
  end if;

  if v_payment.status = 'requires_review' then
    return query
    select
      v_payment.id,
      v_payment.company_id,
      v_payment.plan,
      0,
      true;
    return;
  end if;

  if v_payment.status <> 'pending' then
    raise exception 'PAYMENT_NOT_PENDING';
  end if;

  v_completed_at := coalesce(p_completed_at, now());
  v_credits := case
    when v_payment.plan = 'starter' then 300
    when v_payment.plan = 'professional' then 1200
    else 0
  end;

  v_period_start := coalesce(v_payment.period_start, v_payment.scheduled_activation_at, now());
  v_period_end := coalesce(v_payment.period_end, v_period_start + interval '1 month');
  v_is_paid_scheduled_downgrade := v_payment.scheduled_change_kind = 'paid_downgrade';

  select *
    into v_company_plan
  from public.company_plans cp
  where cp.company_id = v_payment.company_id
  for update;
  v_company_plan_found := found;

  if v_is_paid_scheduled_downgrade then
    if not v_company_plan_found
      or v_payment.plan <> 'starter'
      or v_payment.scheduled_source_plan <> 'professional'
      or v_payment.scheduled_source_period_end is null
      or v_payment.scheduled_activation_at is null
      or v_company_plan.current_plan is distinct from v_payment.scheduled_source_plan
      or v_company_plan.period_end is distinct from v_payment.scheduled_source_period_end
    then
      update public.payments
        set status = 'requires_review',
            completed_at = v_completed_at,
            provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
            credits_granted = 0,
            failed_at = v_completed_at,
            fail_reason = 'STALE_SCHEDULED_PAYMENT_REQUIRES_REVIEW'
      where id = v_payment.id;

      return query
      select
        v_payment.id,
        v_payment.company_id,
        v_payment.plan,
        0,
        false;
      return;
    end if;

    v_period_start := v_payment.scheduled_activation_at;
    v_period_end := coalesce(v_payment.period_end, v_period_start + interval '1 month');

    if v_completed_at < v_payment.scheduled_source_period_end
      and v_payment.scheduled_activation_at > v_completed_at
    then
      v_defer_plan_activation := true;
    elsif v_completed_at >= v_payment.scheduled_source_period_end then
      v_period_start := v_completed_at;
      v_period_end := v_period_start + interval '1 month';
    end if;
  end if;

  if v_defer_plan_activation
    and v_company_plan.scheduled_payment_id is not null
    and v_company_plan.scheduled_payment_id <> v_payment.id
  then
    raise exception 'PAID_SCHEDULE_EXISTS';
  end if;

  v_granted_credits := case when v_defer_plan_activation then 0 else v_credits end;

  update public.payments
    set status = 'completed',
        completed_at = v_completed_at,
        provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
        credits_granted = coalesce(v_payment.credits_granted, v_granted_credits),
        period_start = v_period_start,
        period_end = v_period_end,
        failed_at = null,
        fail_reason = null
  where id = v_payment.id;

  if v_defer_plan_activation then
    update public.company_plans cp
      set scheduled_plan = v_payment.plan,
          scheduled_plan_effective_at = v_period_start,
          scheduled_payment_id = v_payment.id,
          updated_at = now()
    where cp.company_id = v_payment.company_id;

    return query
    select
      v_payment.id,
      v_payment.company_id,
      v_payment.plan,
      0,
      false;
    return;
  end if;

  if v_company_plan_found then
    v_existing_scheduled_plan := v_company_plan.scheduled_plan;
    v_existing_scheduled_effective_at := v_company_plan.scheduled_plan_effective_at;
    v_clear_scheduled := v_existing_scheduled_plan is not null
      and (
        v_existing_scheduled_plan = v_payment.plan
        or (
          v_existing_scheduled_effective_at is not null
          and v_existing_scheduled_effective_at <= v_period_start
        )
      );

    update public.company_plans cp
      set current_plan = v_payment.plan,
          trial_expires_at = null,
          period_start = v_period_start,
          period_end = v_period_end,
          expires_at = v_period_end,
          robokassa_inv_id = p_inv_id::text,
          auto_renew = coalesce(v_payment.activate_auto_renew, true),
          scheduled_plan = case when v_clear_scheduled then null else cp.scheduled_plan end,
          scheduled_plan_effective_at = case when v_clear_scheduled then null else cp.scheduled_plan_effective_at end,
          scheduled_payment_id = case when v_clear_scheduled then null else cp.scheduled_payment_id end,
          updated_at = now()
    where cp.company_id = v_payment.company_id;
  else
    insert into public.company_plans (
      company_id,
      current_plan,
      period_start,
      period_end,
      expires_at,
      robokassa_inv_id,
      auto_renew,
      scheduled_plan,
      scheduled_plan_effective_at,
      scheduled_payment_id
    )
    values (
      v_payment.company_id,
      v_payment.plan,
      v_period_start,
      v_period_end,
      v_period_end,
      p_inv_id::text,
      coalesce(v_payment.activate_auto_renew, true),
      null,
      null,
      null
    )
    on conflict (company_id) do update
      set current_plan = excluded.current_plan,
          period_start = excluded.period_start,
          period_end = excluded.period_end,
          expires_at = excluded.expires_at,
          robokassa_inv_id = excluded.robokassa_inv_id,
          auto_renew = excluded.auto_renew,
          scheduled_plan = null,
          scheduled_plan_effective_at = null,
          scheduled_payment_id = null,
          updated_at = now();
  end if;

  if v_credits > 0 then
    insert into public.credit_ledger (
      company_id,
      delta,
      reason,
      reference_type,
      reference_id,
      notes
    )
    values (
      v_payment.company_id,
      v_credits,
      'grant',
      'plan_payment',
      v_payment.id,
      format('Plan payment inv_id=%s plan=%s', p_inv_id, v_payment.plan)
    )
    on conflict do nothing;
  end if;

  return query
  select
    v_payment.id,
    v_payment.company_id,
    v_payment.plan,
    v_credits,
    false;
end;
$$;

create or replace function public.prevent_paid_schedule_overwrite()
returns trigger
language plpgsql
set search_path = public
as $$
begin
  if old.scheduled_payment_id is not null
    and not (
      new.scheduled_payment_id is null
      and new.scheduled_plan is null
      and new.scheduled_plan_effective_at is null
      and new.current_plan = old.scheduled_plan
    )
    and not (
      new.scheduled_payment_id is null
      and new.scheduled_plan is null
      and new.scheduled_plan_effective_at is null
      and exists (
        select 1
        from public.payments p
        where p.id = old.scheduled_payment_id
          and p.status in ('requires_review', 'refunded')
      )
    )
    and (
      old.scheduled_payment_id is distinct from new.scheduled_payment_id
      or old.scheduled_plan is distinct from new.scheduled_plan
      or old.scheduled_plan_effective_at is distinct from new.scheduled_plan_effective_at
    )
  then
    raise exception 'PAID_SCHEDULE_CANNOT_OVERWRITE';
  end if;

  return new;
end;
$$;

drop trigger if exists company_plans_prevent_paid_schedule_overwrite on public.company_plans;
create trigger company_plans_prevent_paid_schedule_overwrite
  before update on public.company_plans
  for each row
  execute function public.prevent_paid_schedule_overwrite();

create or replace function public.mark_paid_scheduled_downgrade_requires_review(
  p_company_id uuid,
  p_reason text default 'MANUAL_REVIEW'
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_plan public.company_plans;
  v_payment_id uuid;
begin
  select *
    into v_plan
  from public.company_plans cp
  where cp.company_id = p_company_id
  for update;

  if not found or v_plan.scheduled_payment_id is null then
    raise exception 'PAID_SCHEDULE_NOT_FOUND';
  end if;

  v_payment_id := v_plan.scheduled_payment_id;

  update public.payments p
    set status = 'requires_review',
        failed_at = coalesce(p.failed_at, now()),
        fail_reason = coalesce(nullif(trim(p_reason), ''), 'MANUAL_REVIEW')
  where p.id = v_payment_id
    and p.status in ('pending', 'completed', 'requires_review');

  update public.company_plans cp
    set scheduled_plan = null,
        scheduled_plan_effective_at = null,
        scheduled_payment_id = null,
        updated_at = now()
  where cp.company_id = p_company_id;

  return v_payment_id;
end;
$$;

revoke all on function public.mark_paid_scheduled_downgrade_requires_review(uuid, text) from public, anon, authenticated;
grant execute on function public.mark_paid_scheduled_downgrade_requires_review(uuid, text) to service_role;


-- ------------------------------------------------------------------
-- Source: supabase/sql/billing_paid_scheduled_downgrade_enterprise_supersede_v1.sql
-- ------------------------------------------------------------------
-- Billing paid scheduled downgrade enterprise supersede v1
--
-- Goals:
-- - Let platform-admin Enterprise qualification supersede a paid scheduled downgrade safely.
-- - Keep the active plan switch and payment review marker in one database transaction.

create or replace function public.qualify_company_enterprise_plan(
  p_company_id uuid,
  p_reason text default 'ENTERPRISE_SUPERSEDE'
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_plan public.company_plans;
begin
  select *
    into v_plan
  from public.company_plans cp
  where cp.company_id = p_company_id
  for update;

  if not found then
    insert into public.company_plans (
      company_id,
      current_plan,
      trial_expires_at,
      intended_plan,
      expires_at,
      period_start,
      period_end,
      robokassa_inv_id,
      auto_renew,
      scheduled_plan,
      scheduled_plan_effective_at,
      scheduled_payment_id
    )
    values (
      p_company_id,
      'enterprise',
      null,
      null,
      null,
      null,
      null,
      null,
      false,
      null,
      null,
      null
    );
    return true;
  end if;

  if v_plan.scheduled_payment_id is not null then
    update public.payments p
      set status = 'requires_review',
          failed_at = coalesce(p.failed_at, now()),
          fail_reason = coalesce(nullif(trim(p_reason), ''), 'ENTERPRISE_SUPERSEDE')
    where p.id = v_plan.scheduled_payment_id
      and p.status in ('pending', 'completed', 'requires_review');
  end if;

  update public.company_plans cp
    set current_plan = 'enterprise',
        trial_expires_at = null,
        intended_plan = null,
        expires_at = null,
        period_start = null,
        period_end = null,
        robokassa_inv_id = null,
        auto_renew = false,
        scheduled_plan = null,
        scheduled_plan_effective_at = null,
        scheduled_payment_id = null,
        updated_at = now()
  where cp.company_id = p_company_id;

  return true;
end;
$$;

revoke all on function public.qualify_company_enterprise_plan(uuid, text) from public, anon, authenticated;
grant execute on function public.qualify_company_enterprise_plan(uuid, text) to service_role;


-- ------------------------------------------------------------------
-- Source: supabase/sql/billing_checkout_pending_immediate_idempotency_v1.sql
-- ------------------------------------------------------------------
-- Billing checkout pending immediate idempotency v1
--
-- Goals:
-- - Prevent duplicate pending immediate self-service invoices for the same company and plan.
-- - Keep paid scheduled downgrades out of this guard; they have their own period-based protection.
-- - Leave legacy pending duplicates untouched; runtime reuses existing pending invoices.

create unique index if not exists idx_payments_pending_immediate_self_service_once
  on public.payments (company_id, plan)
  where status = 'pending'
    and is_recurring = false
    and scheduled_change_kind is null
    and created_at is not null
    and created_at >= timestamptz '2026-04-29 00:00:00+00';


-- ------------------------------------------------------------------
-- Source: supabase/sql/billing_immediate_checkout_lifecycle_v1.sql
-- ------------------------------------------------------------------
-- Billing immediate checkout lifecycle v1
--
-- Goals:
-- - Give new self-service immediate Robokassa invoices an explicit checkout TTL.
-- - Reuse only matching, unexpired checkout intents.
-- - Move late or state-conflicting immediate payments to manual review without changing access.
-- - Expire only new-model immediate pending invoices; leave legacy pending invoices untouched.

alter table public.payments
  add column if not exists checkout_expires_at timestamptz null;

drop index if exists public.idx_payments_pending_immediate_self_service_once;

create unique index if not exists idx_payments_pending_immediate_checkout_intent_once
  on public.payments (company_id, plan, amount, currency, activate_auto_renew)
  where status = 'pending'
    and is_recurring = false
    and scheduled_change_kind is null
    and checkout_expires_at is not null;

create or replace function public.expire_pending_immediate_checkouts(
  p_now timestamptz default now()
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_count integer := 0;
begin
  update public.payments p
    set status = 'failed',
        failed_at = coalesce(p.failed_at, p_now),
        fail_reason = coalesce(p.fail_reason, 'EXPIRED')
  where p.status = 'pending'
    and p.is_recurring = false
    and p.scheduled_change_kind is null
    and p.checkout_expires_at is not null
    and p.checkout_expires_at < p_now;

  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

revoke all on function public.expire_pending_immediate_checkouts(timestamptz) from public, anon, authenticated;
grant execute on function public.expire_pending_immediate_checkouts(timestamptz) to service_role;

create or replace function public.finalize_robokassa_payment(
  p_inv_id integer,
  p_provider_id text,
  p_completed_at timestamptz default now()
)
returns table (
  payment_id uuid,
  company_id uuid,
  plan text,
  credits_granted integer,
  already_completed boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_payment public.payments;
  v_company_plan public.company_plans;
  v_completed_at timestamptz;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_credits integer;
  v_existing_scheduled_plan text;
  v_existing_scheduled_effective_at timestamptz;
  v_clear_scheduled boolean := false;
  v_company_plan_found boolean := false;
  v_is_paid_scheduled_downgrade boolean := false;
  v_is_immediate_checkout boolean := false;
  v_defer_plan_activation boolean := false;
  v_granted_credits integer := 0;
  v_current_plan_weight integer := 0;
  v_payment_plan_weight integer := 0;
  v_company_plan_active boolean := false;
begin
  select *
    into v_payment
  from public.payments
  where inv_id = p_inv_id
  for update;

  if not found then
    raise exception 'PAYMENT_NOT_FOUND';
  end if;

  if v_payment.status = 'completed' then
    return query
    select
      v_payment.id,
      v_payment.company_id,
      v_payment.plan,
      coalesce(v_payment.credits_granted, 0),
      true;
    return;
  end if;

  if v_payment.status = 'requires_review' then
    return query
    select
      v_payment.id,
      v_payment.company_id,
      v_payment.plan,
      0,
      true;
    return;
  end if;

  if v_payment.status <> 'pending' then
    raise exception 'PAYMENT_NOT_PENDING';
  end if;

  v_completed_at := coalesce(p_completed_at, now());
  v_credits := case
    when v_payment.plan = 'starter' then 300
    when v_payment.plan = 'professional' then 1200
    else 0
  end;

  v_period_start := coalesce(v_payment.period_start, v_payment.scheduled_activation_at, now());
  v_period_end := coalesce(v_payment.period_end, v_period_start + interval '1 month');
  v_is_paid_scheduled_downgrade := v_payment.scheduled_change_kind = 'paid_downgrade';
  v_is_immediate_checkout := v_payment.is_recurring = false
    and v_payment.scheduled_change_kind is null;

  select *
    into v_company_plan
  from public.company_plans cp
  where cp.company_id = v_payment.company_id
  for update;
  v_company_plan_found := found;

  if v_is_immediate_checkout then
    if v_payment.checkout_expires_at is not null
      and v_completed_at > v_payment.checkout_expires_at
    then
      update public.payments
        set status = 'requires_review',
            completed_at = v_completed_at,
            provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
            credits_granted = 0,
            failed_at = v_completed_at,
            fail_reason = 'CHECKOUT_EXPIRED_REQUIRES_REVIEW'
      where id = v_payment.id;

      return query
      select
        v_payment.id,
        v_payment.company_id,
        v_payment.plan,
        0,
        false;
      return;
    end if;

    if v_company_plan_found then
      v_current_plan_weight := case v_company_plan.current_plan
        when 'trial' then 0
        when 'starter' then 1
        when 'professional' then 2
        when 'enterprise' then 3
        else 0
      end;
      v_payment_plan_weight := case v_payment.plan
        when 'starter' then 1
        when 'professional' then 2
        when 'enterprise' then 3
        else 0
      end;
      v_company_plan_active := v_company_plan.current_plan = 'enterprise'
        or v_company_plan.period_end is null
        or v_company_plan.period_end > v_completed_at;

      if v_company_plan.current_plan = 'enterprise'
        or (
          v_company_plan_active
          and v_current_plan_weight > v_payment_plan_weight
        )
      then
        update public.payments
          set status = 'requires_review',
              completed_at = v_completed_at,
              provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
              credits_granted = 0,
              failed_at = v_completed_at,
              fail_reason = case
                when v_company_plan.current_plan = 'enterprise' then 'ENTERPRISE_REQUIRES_REVIEW'
                else 'ACTIVE_DOWNGRADE_REQUIRES_REVIEW'
              end
        where id = v_payment.id;

        return query
        select
          v_payment.id,
          v_payment.company_id,
          v_payment.plan,
          0,
          false;
        return;
      end if;
    end if;

    v_period_start := v_completed_at;
    v_period_end := v_period_start + interval '1 month';
  end if;

  if v_is_paid_scheduled_downgrade then
    if not v_company_plan_found
      or v_payment.plan <> 'starter'
      or v_payment.scheduled_source_plan <> 'professional'
      or v_payment.scheduled_source_period_end is null
      or v_payment.scheduled_activation_at is null
      or v_company_plan.current_plan is distinct from v_payment.scheduled_source_plan
      or v_company_plan.period_end is distinct from v_payment.scheduled_source_period_end
    then
      update public.payments
        set status = 'requires_review',
            completed_at = v_completed_at,
            provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
            credits_granted = 0,
            failed_at = v_completed_at,
            fail_reason = 'STALE_SCHEDULED_PAYMENT_REQUIRES_REVIEW'
      where id = v_payment.id;

      return query
      select
        v_payment.id,
        v_payment.company_id,
        v_payment.plan,
        0,
        false;
      return;
    end if;

    v_period_start := v_payment.scheduled_activation_at;
    v_period_end := coalesce(v_payment.period_end, v_period_start + interval '1 month');

    if v_completed_at < v_payment.scheduled_source_period_end
      and v_payment.scheduled_activation_at > v_completed_at
    then
      v_defer_plan_activation := true;
    elsif v_completed_at >= v_payment.scheduled_source_period_end then
      v_period_start := v_completed_at;
      v_period_end := v_period_start + interval '1 month';
    end if;
  end if;

  if v_defer_plan_activation
    and v_company_plan.scheduled_payment_id is not null
    and v_company_plan.scheduled_payment_id <> v_payment.id
  then
    raise exception 'PAID_SCHEDULE_EXISTS';
  end if;

  v_granted_credits := case when v_defer_plan_activation then 0 else v_credits end;

  update public.payments
    set status = 'completed',
        completed_at = v_completed_at,
        provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
        credits_granted = coalesce(v_payment.credits_granted, v_granted_credits),
        period_start = v_period_start,
        period_end = v_period_end,
        failed_at = null,
        fail_reason = null
  where id = v_payment.id;

  if v_defer_plan_activation then
    update public.company_plans cp
      set scheduled_plan = v_payment.plan,
          scheduled_plan_effective_at = v_period_start,
          scheduled_payment_id = v_payment.id,
          updated_at = now()
    where cp.company_id = v_payment.company_id;

    return query
    select
      v_payment.id,
      v_payment.company_id,
      v_payment.plan,
      0,
      false;
    return;
  end if;

  if v_company_plan_found then
    v_existing_scheduled_plan := v_company_plan.scheduled_plan;
    v_existing_scheduled_effective_at := v_company_plan.scheduled_plan_effective_at;
    v_clear_scheduled := v_existing_scheduled_plan is not null
      and (
        v_existing_scheduled_plan = v_payment.plan
        or (
          v_existing_scheduled_effective_at is not null
          and v_existing_scheduled_effective_at <= v_period_start
        )
      );

    update public.company_plans cp
      set current_plan = v_payment.plan,
          trial_expires_at = null,
          period_start = v_period_start,
          period_end = v_period_end,
          expires_at = v_period_end,
          robokassa_inv_id = p_inv_id::text,
          auto_renew = coalesce(v_payment.activate_auto_renew, true),
          scheduled_plan = case when v_clear_scheduled then null else cp.scheduled_plan end,
          scheduled_plan_effective_at = case when v_clear_scheduled then null else cp.scheduled_plan_effective_at end,
          scheduled_payment_id = case when v_clear_scheduled then null else cp.scheduled_payment_id end,
          updated_at = now()
    where cp.company_id = v_payment.company_id;
  else
    insert into public.company_plans (
      company_id,
      current_plan,
      period_start,
      period_end,
      expires_at,
      robokassa_inv_id,
      auto_renew,
      scheduled_plan,
      scheduled_plan_effective_at,
      scheduled_payment_id
    )
    values (
      v_payment.company_id,
      v_payment.plan,
      v_period_start,
      v_period_end,
      v_period_end,
      p_inv_id::text,
      coalesce(v_payment.activate_auto_renew, true),
      null,
      null,
      null
    )
    on conflict (company_id) do update
      set current_plan = excluded.current_plan,
          period_start = excluded.period_start,
          period_end = excluded.period_end,
          expires_at = excluded.expires_at,
          robokassa_inv_id = excluded.robokassa_inv_id,
          auto_renew = excluded.auto_renew,
          scheduled_plan = null,
          scheduled_plan_effective_at = null,
          scheduled_payment_id = null,
          updated_at = now();
  end if;

  if v_credits > 0 then
    insert into public.credit_ledger (
      company_id,
      delta,
      reason,
      reference_type,
      reference_id,
      notes
    )
    values (
      v_payment.company_id,
      v_credits,
      'grant',
      'plan_payment',
      v_payment.id,
      format('Plan payment inv_id=%s plan=%s', p_inv_id, v_payment.plan)
    )
    on conflict do nothing;
  end if;

  return query
  select
    v_payment.id,
    v_payment.company_id,
    v_payment.plan,
    v_credits,
    false;
end;
$$;


-- ------------------------------------------------------------------
-- Source: supabase/sql/billing_expired_immediate_checkout_finalize_review_v1.sql
-- ------------------------------------------------------------------
-- Billing expired immediate checkout finalize review v1
--
-- Allows a valid Robokassa webhook for a new-model immediate checkout that was
-- already expired by cleanup to move the payment into manual review instead of
-- failing the webhook with PAYMENT_NOT_PENDING.

create or replace function public.finalize_robokassa_payment(
  p_inv_id integer,
  p_provider_id text,
  p_completed_at timestamptz default now()
)
returns table (
  payment_id uuid,
  company_id uuid,
  plan text,
  credits_granted integer,
  already_completed boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_payment public.payments;
  v_company_plan public.company_plans;
  v_completed_at timestamptz;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_credits integer;
  v_existing_scheduled_plan text;
  v_existing_scheduled_effective_at timestamptz;
  v_clear_scheduled boolean := false;
  v_company_plan_found boolean := false;
  v_is_paid_scheduled_downgrade boolean := false;
  v_is_immediate_checkout boolean := false;
  v_defer_plan_activation boolean := false;
  v_granted_credits integer := 0;
  v_current_plan_weight integer := 0;
  v_payment_plan_weight integer := 0;
  v_company_plan_active boolean := false;
begin
  select *
    into v_payment
  from public.payments
  where inv_id = p_inv_id
  for update;

  if not found then
    raise exception 'PAYMENT_NOT_FOUND';
  end if;

  if v_payment.status = 'completed' then
    return query
    select
      v_payment.id,
      v_payment.company_id,
      v_payment.plan,
      coalesce(v_payment.credits_granted, 0),
      true;
    return;
  end if;

  if v_payment.status = 'requires_review' then
    return query
    select
      v_payment.id,
      v_payment.company_id,
      v_payment.plan,
      0,
      true;
    return;
  end if;

  v_completed_at := coalesce(p_completed_at, now());

  if v_payment.status = 'failed'
    and v_payment.fail_reason = 'EXPIRED'
    and v_payment.checkout_expires_at is not null
    and v_payment.is_recurring = false
    and v_payment.scheduled_change_kind is null
  then
    update public.payments
      set status = 'requires_review',
          completed_at = v_completed_at,
          provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
          credits_granted = 0,
          fail_reason = 'CHECKOUT_EXPIRED_REQUIRES_REVIEW'
    where id = v_payment.id;

    return query
    select
      v_payment.id,
      v_payment.company_id,
      v_payment.plan,
      0,
      false;
    return;
  end if;

  if v_payment.status <> 'pending' then
    raise exception 'PAYMENT_NOT_PENDING';
  end if;

  v_credits := case
    when v_payment.plan = 'starter' then 500
    when v_payment.plan = 'professional' then 2000
    else 0
  end;

  v_period_start := coalesce(v_payment.period_start, v_payment.scheduled_activation_at, now());
  v_period_end := coalesce(v_payment.period_end, v_period_start + interval '1 month');
  v_is_paid_scheduled_downgrade := v_payment.scheduled_change_kind = 'paid_downgrade';
  v_is_immediate_checkout := v_payment.is_recurring = false
    and v_payment.scheduled_change_kind is null;

  select *
    into v_company_plan
  from public.company_plans cp
  where cp.company_id = v_payment.company_id
  for update;
  v_company_plan_found := found;

  if v_is_immediate_checkout then
    if v_payment.checkout_expires_at is not null
      and v_completed_at > v_payment.checkout_expires_at
    then
      update public.payments
        set status = 'requires_review',
            completed_at = v_completed_at,
            provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
            credits_granted = 0,
            failed_at = v_completed_at,
            fail_reason = 'CHECKOUT_EXPIRED_REQUIRES_REVIEW'
      where id = v_payment.id;

      return query
      select
        v_payment.id,
        v_payment.company_id,
        v_payment.plan,
        0,
        false;
      return;
    end if;

    if v_company_plan_found then
      v_current_plan_weight := case v_company_plan.current_plan
        when 'trial' then 0
        when 'starter' then 1
        when 'professional' then 2
        when 'enterprise' then 3
        else 0
      end;
      v_payment_plan_weight := case v_payment.plan
        when 'starter' then 1
        when 'professional' then 2
        when 'enterprise' then 3
        else 0
      end;
      v_company_plan_active := v_company_plan.current_plan = 'enterprise'
        or v_company_plan.period_end is null
        or v_company_plan.period_end > v_completed_at;

      if v_company_plan.current_plan = 'enterprise'
        or (
          v_company_plan_active
          and v_current_plan_weight > v_payment_plan_weight
        )
      then
        update public.payments
          set status = 'requires_review',
              completed_at = v_completed_at,
              provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
              credits_granted = 0,
              failed_at = v_completed_at,
              fail_reason = case
                when v_company_plan.current_plan = 'enterprise' then 'ENTERPRISE_REQUIRES_REVIEW'
                else 'ACTIVE_DOWNGRADE_REQUIRES_REVIEW'
              end
        where id = v_payment.id;

        return query
        select
          v_payment.id,
          v_payment.company_id,
          v_payment.plan,
          0,
          false;
        return;
      end if;
    end if;

    v_period_start := v_completed_at;
    v_period_end := v_period_start + interval '1 month';
  end if;

  if v_is_paid_scheduled_downgrade then
    if not v_company_plan_found
      or v_payment.plan <> 'starter'
      or v_payment.scheduled_source_plan <> 'professional'
      or v_payment.scheduled_source_period_end is null
      or v_payment.scheduled_activation_at is null
      or v_company_plan.current_plan is distinct from v_payment.scheduled_source_plan
      or v_company_plan.period_end is distinct from v_payment.scheduled_source_period_end
    then
      update public.payments
        set status = 'requires_review',
            completed_at = v_completed_at,
            provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
            credits_granted = 0,
            failed_at = v_completed_at,
            fail_reason = 'STALE_SCHEDULED_PAYMENT_REQUIRES_REVIEW'
      where id = v_payment.id;

      return query
      select
        v_payment.id,
        v_payment.company_id,
        v_payment.plan,
        0,
        false;
      return;
    end if;

    v_period_start := v_payment.scheduled_activation_at;
    v_period_end := coalesce(v_payment.period_end, v_period_start + interval '1 month');

    if v_completed_at < v_payment.scheduled_source_period_end
      and v_payment.scheduled_activation_at > v_completed_at
    then
      v_defer_plan_activation := true;
    elsif v_completed_at >= v_payment.scheduled_source_period_end then
      v_period_start := v_completed_at;
      v_period_end := v_period_start + interval '1 month';
    end if;
  end if;

  if v_defer_plan_activation
    and v_company_plan.scheduled_payment_id is not null
    and v_company_plan.scheduled_payment_id <> v_payment.id
  then
    raise exception 'PAID_SCHEDULE_EXISTS';
  end if;

  v_granted_credits := case when v_defer_plan_activation then 0 else v_credits end;

  update public.payments
    set status = 'completed',
        completed_at = v_completed_at,
        provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
        credits_granted = coalesce(v_payment.credits_granted, v_granted_credits),
        period_start = v_period_start,
        period_end = v_period_end,
        failed_at = null,
        fail_reason = null
  where id = v_payment.id;

  if v_defer_plan_activation then
    update public.company_plans cp
      set scheduled_plan = v_payment.plan,
          scheduled_plan_effective_at = v_period_start,
          scheduled_payment_id = v_payment.id,
          updated_at = now()
    where cp.company_id = v_payment.company_id;

    return query
    select
      v_payment.id,
      v_payment.company_id,
      v_payment.plan,
      0,
      false;
    return;
  end if;

  if v_company_plan_found then
    v_existing_scheduled_plan := v_company_plan.scheduled_plan;
    v_existing_scheduled_effective_at := v_company_plan.scheduled_plan_effective_at;
    v_clear_scheduled := v_existing_scheduled_plan is not null
      and (
        v_existing_scheduled_plan = v_payment.plan
        or (
          v_existing_scheduled_effective_at is not null
          and v_existing_scheduled_effective_at <= v_period_start
        )
      );

    update public.company_plans cp
      set current_plan = v_payment.plan,
          trial_expires_at = null,
          period_start = v_period_start,
          period_end = v_period_end,
          expires_at = v_period_end,
          robokassa_inv_id = p_inv_id::text,
          auto_renew = coalesce(v_payment.activate_auto_renew, true),
          scheduled_plan = case when v_clear_scheduled then null else cp.scheduled_plan end,
          scheduled_plan_effective_at = case when v_clear_scheduled then null else cp.scheduled_plan_effective_at end,
          scheduled_payment_id = case when v_clear_scheduled then null else cp.scheduled_payment_id end,
          updated_at = now()
    where cp.company_id = v_payment.company_id;
  else
    insert into public.company_plans (
      company_id,
      current_plan,
      period_start,
      period_end,
      expires_at,
      robokassa_inv_id,
      auto_renew,
      scheduled_plan,
      scheduled_plan_effective_at,
      scheduled_payment_id
    )
    values (
      v_payment.company_id,
      v_payment.plan,
      v_period_start,
      v_period_end,
      v_period_end,
      p_inv_id::text,
      coalesce(v_payment.activate_auto_renew, true),
      null,
      null,
      null
    )
    on conflict (company_id) do update
      set current_plan = excluded.current_plan,
          period_start = excluded.period_start,
          period_end = excluded.period_end,
          expires_at = excluded.expires_at,
          robokassa_inv_id = excluded.robokassa_inv_id,
          auto_renew = excluded.auto_renew,
          scheduled_plan = null,
          scheduled_plan_effective_at = null,
          scheduled_payment_id = null,
          updated_at = now();
  end if;

  if v_credits > 0 then
    insert into public.credit_ledger (
      company_id,
      delta,
      reason,
      reference_type,
      reference_id,
      notes
    )
    values (
      v_payment.company_id,
      v_credits,
      'grant',
      'plan_payment',
      v_payment.id,
      format('Plan payment inv_id=%s plan=%s', p_inv_id, v_payment.plan)
    )
    on conflict do nothing;
  end if;

  return query
  select
    v_payment.id,
    v_payment.company_id,
    v_payment.plan,
    v_credits,
    false;
end;
$$;

revoke all on function public.finalize_robokassa_payment(integer, text, timestamptz) from public, anon, authenticated;
grant execute on function public.finalize_robokassa_payment(integer, text, timestamptz) to service_role;


-- ------------------------------------------------------------------
-- Source: supabase/sql/billing_recurring_renewal_idempotency_and_mandate_v1.sql
-- ------------------------------------------------------------------
-- Billing recurring renewal idempotency and Robokassa mandate guard v1
--
-- Applied to hiiire via Supabase MCP on 2026-05-02.

alter table public.payments
  add column if not exists recurring_mandate_activated boolean not null default false;

create unique index if not exists idx_payments_recurring_active_period_once
  on public.payments (company_id, parent_inv_id, period_start)
  where is_recurring = true
    and parent_inv_id is not null
    and period_start is not null
    and status in ('pending', 'completed', 'requires_review');

update public.company_plans cp
set auto_renew = false,
    updated_at = now()
where cp.auto_renew = true
  and cp.current_plan in ('starter', 'professional')
  and not exists (
    select 1
    from public.payments p
    where p.company_id = cp.company_id
      and p.inv_id::text = cp.robokassa_inv_id
      and p.status = 'completed'
      and p.recurring_mandate_activated = true
  );

create or replace function public.set_company_plan_auto_renew(
  p_company_id uuid,
  p_enabled boolean
)
returns table (
  company_id uuid,
  current_plan text,
  auto_renew boolean,
  scheduled_plan text,
  scheduled_plan_effective_at timestamptz,
  scheduled_payment_id uuid
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_plan public.company_plans;
begin
  select *
    into v_plan
  from public.company_plans cp
  where cp.company_id = p_company_id
  for update;

  if not found then
    raise exception 'COMPANY_PLAN_NOT_FOUND';
  end if;

  if p_enabled then
    if not exists (
      select 1
      from public.payments p
      where p.company_id = p_company_id
        and p.inv_id::text = v_plan.robokassa_inv_id
        and p.status = 'completed'
        and p.recurring_mandate_activated = true
    ) then
      raise exception 'NO_RECURRING_PAYMENT';
    end if;

    update public.company_plans cp
      set auto_renew = true,
          updated_at = now()
    where cp.company_id = p_company_id;
  else
    update public.company_plans cp
      set auto_renew = false,
          scheduled_plan = case when v_plan.scheduled_payment_id is null then null else cp.scheduled_plan end,
          scheduled_plan_effective_at = case when v_plan.scheduled_payment_id is null then null else cp.scheduled_plan_effective_at end,
          scheduled_payment_id = case when v_plan.scheduled_payment_id is null then null else cp.scheduled_payment_id end,
          updated_at = now()
    where cp.company_id = p_company_id;
  end if;

  update public.payments p
    set activate_auto_renew = p_enabled and p.recurring_mandate_activated
  where p.company_id = p_company_id
    and p.is_recurring = false
    and p.scheduled_change_kind = 'paid_downgrade'
    and (
      p.status = 'pending'
      or p.id = v_plan.scheduled_payment_id
    );

  return query
  select
    cp.company_id,
    cp.current_plan,
    cp.auto_renew,
    cp.scheduled_plan,
    cp.scheduled_plan_effective_at,
    cp.scheduled_payment_id
  from public.company_plans cp
  where cp.company_id = p_company_id;
end;
$$;

revoke all on function public.set_company_plan_auto_renew(uuid, boolean) from public, anon, authenticated;
grant execute on function public.set_company_plan_auto_renew(uuid, boolean) to service_role;

create or replace function public.finalize_robokassa_payment(
  p_inv_id integer,
  p_provider_id text,
  p_completed_at timestamptz default now()
)
returns table (
  payment_id uuid,
  company_id uuid,
  plan text,
  credits_granted integer,
  already_completed boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_payment public.payments;
  v_company_plan public.company_plans;
  v_completed_at timestamptz;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_credits integer;
  v_existing_scheduled_plan text;
  v_existing_scheduled_effective_at timestamptz;
  v_clear_scheduled boolean := false;
  v_company_plan_found boolean := false;
  v_is_paid_scheduled_downgrade boolean := false;
  v_is_immediate_checkout boolean := false;
  v_defer_plan_activation boolean := false;
  v_granted_credits integer := 0;
  v_current_plan_weight integer := 0;
  v_payment_plan_weight integer := 0;
  v_company_plan_active boolean := false;
  v_recurring_mandate_activated boolean := false;
begin
  select *
    into v_payment
  from public.payments
  where inv_id = p_inv_id
  for update;

  if not found then
    raise exception 'PAYMENT_NOT_FOUND';
  end if;

  if v_payment.status = 'completed' then
    return query
    select v_payment.id, v_payment.company_id, v_payment.plan, coalesce(v_payment.credits_granted, 0), true;
    return;
  end if;

  if v_payment.status = 'requires_review' then
    return query
    select v_payment.id, v_payment.company_id, v_payment.plan, 0, true;
    return;
  end if;

  v_completed_at := coalesce(p_completed_at, now());

  if v_payment.status = 'failed'
    and v_payment.fail_reason = 'EXPIRED'
    and v_payment.checkout_expires_at is not null
    and v_payment.is_recurring = false
    and v_payment.scheduled_change_kind is null
  then
    update public.payments
      set status = 'requires_review',
          completed_at = v_completed_at,
          provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
          credits_granted = 0,
          fail_reason = 'CHECKOUT_EXPIRED_REQUIRES_REVIEW'
    where id = v_payment.id;

    return query
    select v_payment.id, v_payment.company_id, v_payment.plan, 0, false;
    return;
  end if;

  if v_payment.status <> 'pending' then
    raise exception 'PAYMENT_NOT_PENDING';
  end if;

  v_credits := case
    when v_payment.plan = 'starter' then 300
    when v_payment.plan = 'professional' then 1200
    else 0
  end;

  v_period_start := coalesce(v_payment.period_start, v_payment.scheduled_activation_at, now());
  v_period_end := coalesce(v_payment.period_end, v_period_start + interval '1 month');
  v_is_paid_scheduled_downgrade := v_payment.scheduled_change_kind = 'paid_downgrade';
  v_is_immediate_checkout := v_payment.is_recurring = false and v_payment.scheduled_change_kind is null;

  select *
    into v_company_plan
  from public.company_plans cp
  where cp.company_id = v_payment.company_id
  for update;
  v_company_plan_found := found;

  if v_is_immediate_checkout then
    if v_payment.checkout_expires_at is not null and v_completed_at > v_payment.checkout_expires_at then
      update public.payments
        set status = 'requires_review',
            completed_at = v_completed_at,
            provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
            credits_granted = 0,
            failed_at = v_completed_at,
            fail_reason = 'CHECKOUT_EXPIRED_REQUIRES_REVIEW'
      where id = v_payment.id;

      return query
      select v_payment.id, v_payment.company_id, v_payment.plan, 0, false;
      return;
    end if;

    if v_company_plan_found then
      v_current_plan_weight := case v_company_plan.current_plan
        when 'trial' then 0
        when 'starter' then 1
        when 'professional' then 2
        when 'enterprise' then 3
        else 0
      end;
      v_payment_plan_weight := case v_payment.plan
        when 'starter' then 1
        when 'professional' then 2
        when 'enterprise' then 3
        else 0
      end;
      v_company_plan_active := v_company_plan.current_plan = 'enterprise'
        or v_company_plan.period_end is null
        or v_company_plan.period_end > v_completed_at;

      if v_company_plan.current_plan = 'enterprise'
        or (v_company_plan_active and v_current_plan_weight > v_payment_plan_weight)
      then
        update public.payments
          set status = 'requires_review',
              completed_at = v_completed_at,
              provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
              credits_granted = 0,
              failed_at = v_completed_at,
              fail_reason = case
                when v_company_plan.current_plan = 'enterprise' then 'ENTERPRISE_REQUIRES_REVIEW'
                else 'ACTIVE_DOWNGRADE_REQUIRES_REVIEW'
              end
        where id = v_payment.id;

        return query
        select v_payment.id, v_payment.company_id, v_payment.plan, 0, false;
        return;
      end if;
    end if;

    v_period_start := v_completed_at;
    v_period_end := v_period_start + interval '1 month';
  end if;

  if v_is_paid_scheduled_downgrade then
    if not v_company_plan_found
      or v_payment.plan <> 'starter'
      or v_payment.scheduled_source_plan <> 'professional'
      or v_payment.scheduled_source_period_end is null
      or v_payment.scheduled_activation_at is null
      or v_company_plan.current_plan is distinct from v_payment.scheduled_source_plan
      or v_company_plan.period_end is distinct from v_payment.scheduled_source_period_end
    then
      update public.payments
        set status = 'requires_review',
            completed_at = v_completed_at,
            provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
            credits_granted = 0,
            failed_at = v_completed_at,
            fail_reason = 'STALE_SCHEDULED_PAYMENT_REQUIRES_REVIEW'
      where id = v_payment.id;

      return query
      select v_payment.id, v_payment.company_id, v_payment.plan, 0, false;
      return;
    end if;

    v_period_start := v_payment.scheduled_activation_at;
    v_period_end := coalesce(v_payment.period_end, v_period_start + interval '1 month');

    if v_completed_at < v_payment.scheduled_source_period_end
      and v_payment.scheduled_activation_at > v_completed_at
    then
      v_defer_plan_activation := true;
    elsif v_completed_at >= v_payment.scheduled_source_period_end then
      v_period_start := v_completed_at;
      v_period_end := v_period_start + interval '1 month';
    end if;
  end if;

  if v_defer_plan_activation
    and v_company_plan.scheduled_payment_id is not null
    and v_company_plan.scheduled_payment_id <> v_payment.id
  then
    raise exception 'PAID_SCHEDULE_EXISTS';
  end if;

  v_granted_credits := case when v_defer_plan_activation then 0 else v_credits end;
  v_recurring_mandate_activated := v_payment.recurring_mandate_activated or v_payment.is_recurring;

  update public.payments
    set status = 'completed',
        completed_at = v_completed_at,
        provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
        credits_granted = coalesce(v_payment.credits_granted, v_granted_credits),
        period_start = v_period_start,
        period_end = v_period_end,
        recurring_mandate_activated = v_recurring_mandate_activated,
        failed_at = null,
        fail_reason = null
  where id = v_payment.id;

  if v_defer_plan_activation then
    update public.company_plans cp
      set scheduled_plan = v_payment.plan,
          scheduled_plan_effective_at = v_period_start,
          scheduled_payment_id = v_payment.id,
          updated_at = now()
    where cp.company_id = v_payment.company_id;

    return query
    select v_payment.id, v_payment.company_id, v_payment.plan, 0, false;
    return;
  end if;

  if v_company_plan_found then
    v_existing_scheduled_plan := v_company_plan.scheduled_plan;
    v_existing_scheduled_effective_at := v_company_plan.scheduled_plan_effective_at;
    v_clear_scheduled := v_existing_scheduled_plan is not null
      and (
        v_existing_scheduled_plan = v_payment.plan
        or (v_existing_scheduled_effective_at is not null and v_existing_scheduled_effective_at <= v_period_start)
      );

    update public.company_plans cp
      set current_plan = v_payment.plan,
          trial_expires_at = null,
          period_start = v_period_start,
          period_end = v_period_end,
          expires_at = v_period_end,
          robokassa_inv_id = p_inv_id::text,
          auto_renew = coalesce(v_payment.activate_auto_renew, false) and v_recurring_mandate_activated,
          scheduled_plan = case when v_clear_scheduled then null else cp.scheduled_plan end,
          scheduled_plan_effective_at = case when v_clear_scheduled then null else cp.scheduled_plan_effective_at end,
          scheduled_payment_id = case when v_clear_scheduled then null else cp.scheduled_payment_id end,
          updated_at = now()
    where cp.company_id = v_payment.company_id;
  else
    insert into public.company_plans (
      company_id,
      current_plan,
      period_start,
      period_end,
      expires_at,
      robokassa_inv_id,
      auto_renew,
      scheduled_plan,
      scheduled_plan_effective_at,
      scheduled_payment_id
    )
    values (
      v_payment.company_id,
      v_payment.plan,
      v_period_start,
      v_period_end,
      v_period_end,
      p_inv_id::text,
      coalesce(v_payment.activate_auto_renew, false) and v_recurring_mandate_activated,
      null,
      null,
      null
    )
    on conflict (company_id) do update
      set current_plan = excluded.current_plan,
          period_start = excluded.period_start,
          period_end = excluded.period_end,
          expires_at = excluded.expires_at,
          robokassa_inv_id = excluded.robokassa_inv_id,
          auto_renew = excluded.auto_renew,
          scheduled_plan = null,
          scheduled_plan_effective_at = null,
          scheduled_payment_id = null,
          updated_at = now();
  end if;

  if v_credits > 0 then
    insert into public.credit_ledger (
      company_id,
      delta,
      reason,
      reference_type,
      reference_id,
      notes
    )
    values (
      v_payment.company_id,
      v_credits,
      'grant',
      'plan_payment',
      v_payment.id,
      format('Plan payment inv_id=%s plan=%s', p_inv_id, v_payment.plan)
    )
    on conflict do nothing;
  end if;

  return query
  select v_payment.id, v_payment.company_id, v_payment.plan, v_credits, false;
end;
$$;

revoke all on function public.finalize_robokassa_payment(integer, text, timestamptz) from public, anon, authenticated;
grant execute on function public.finalize_robokassa_payment(integer, text, timestamptz) to service_role;


-- ------------------------------------------------------------------
-- Source: supabase/sql/billing_recurring_mandate_legacy_backfill_v1.sql
-- ------------------------------------------------------------------
-- Billing recurring mandate legacy backfill v1
--
-- The previous migration introduced `payments.recurring_mandate_activated`.
-- Legacy completed payments do not have this flag, but payments created by
-- checkout while recurring billing was enabled already have
-- `activate_auto_renew=true`; before this flag existed, that was the app-side
-- signal used to send Robokassa checkout with `Recurring=true`.

update public.payments p
set recurring_mandate_activated = true
where p.status = 'completed'
  and p.recurring_mandate_activated = false
  and (
    coalesce(p.activate_auto_renew, false) = true
    or p.is_recurring = true
  );

-- Restore only plans that were very likely disabled by the immediately
-- preceding conservative migration. Older user/admin opt-outs keep
-- auto_renew=false, but they can be enabled again through the normal API now
-- that the parent payment has the mandate flag.
update public.company_plans cp
set auto_renew = true,
    updated_at = now()
where cp.auto_renew = false
  and cp.current_plan in ('starter', 'professional')
  and cp.robokassa_inv_id is not null
  and cp.updated_at >= now() - interval '2 hours'
  and exists (
    select 1
    from public.payments p
    where p.company_id = cp.company_id
      and p.inv_id::text = cp.robokassa_inv_id
      and p.status = 'completed'
      and p.recurring_mandate_activated = true
      and coalesce(p.activate_auto_renew, false) = true
  );


-- ------------------------------------------------------------------
-- Source: supabase/sql/billing_recurring_root_mandate_invoice_v1.sql
-- ------------------------------------------------------------------
-- Billing recurring root mandate invoice v1
--
-- Robokassa recurring charges must use the first recurring-capable invoice as
-- PreviousInvoiceID. Keep that root mandate separate from the last/current paid
-- invoice stored in company_plans.robokassa_inv_id.

alter table public.company_plans
  add column if not exists recurring_mandate_inv_id text null;

update public.company_plans cp
set recurring_mandate_inv_id = coalesce(
  (
    select case
      when p.is_recurring = true and p.parent_inv_id is not null then p.parent_inv_id::text
      when p.status = 'completed' and p.recurring_mandate_activated = true then p.inv_id::text
      else null
    end
    from public.payments p
    where p.company_id = cp.company_id
      and p.inv_id::text = cp.robokassa_inv_id
    limit 1
  ),
  (
    select p.inv_id::text
    from public.payments p
    where p.company_id = cp.company_id
      and p.status = 'completed'
      and p.is_recurring = false
      and p.recurring_mandate_activated = true
    order by p.completed_at desc nulls last, p.created_at desc
    limit 1
  ),
  cp.recurring_mandate_inv_id
)
where cp.recurring_mandate_inv_id is null
  and cp.robokassa_inv_id is not null
  and (
    exists (
      select 1
      from public.payments p
      where p.company_id = cp.company_id
        and p.inv_id::text = cp.robokassa_inv_id
        and (
          (p.is_recurring = true and p.parent_inv_id is not null)
          or (p.status = 'completed' and p.recurring_mandate_activated = true)
        )
    )
    or exists (
      select 1
      from public.payments p
      where p.company_id = cp.company_id
        and p.status = 'completed'
        and p.is_recurring = false
        and p.recurring_mandate_activated = true
    )
  );

create or replace function public.set_company_plan_auto_renew(
  p_company_id uuid,
  p_enabled boolean
)
returns table (
  company_id uuid,
  current_plan text,
  auto_renew boolean,
  scheduled_plan text,
  scheduled_plan_effective_at timestamptz,
  scheduled_payment_id uuid
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_plan public.company_plans;
  v_mandate_inv_id text;
begin
  select *
    into v_plan
  from public.company_plans cp
  where cp.company_id = p_company_id
  for update;

  if not found then
    raise exception 'COMPANY_PLAN_NOT_FOUND';
  end if;

  v_mandate_inv_id := nullif(trim(coalesce(v_plan.recurring_mandate_inv_id, '')), '');

  if v_mandate_inv_id is null and v_plan.robokassa_inv_id is not null then
    select case
      when p.is_recurring = true and p.parent_inv_id is not null then p.parent_inv_id::text
      when p.status = 'completed' and p.recurring_mandate_activated = true then p.inv_id::text
      else null
    end
      into v_mandate_inv_id
    from public.payments p
    where p.company_id = p_company_id
      and p.inv_id::text = v_plan.robokassa_inv_id
    limit 1;
  end if;

  if p_enabled then
    if v_mandate_inv_id is null or not exists (
      select 1
      from public.payments p
      where p.company_id = p_company_id
        and p.inv_id::text = v_mandate_inv_id
        and p.status = 'completed'
        and p.recurring_mandate_activated = true
    ) then
      raise exception 'NO_RECURRING_PAYMENT';
    end if;

    update public.company_plans cp
      set auto_renew = true,
          recurring_mandate_inv_id = v_mandate_inv_id,
          updated_at = now()
    where cp.company_id = p_company_id;
  else
    update public.company_plans cp
      set auto_renew = false,
          scheduled_plan = case when v_plan.scheduled_payment_id is null then null else cp.scheduled_plan end,
          scheduled_plan_effective_at = case when v_plan.scheduled_payment_id is null then null else cp.scheduled_plan_effective_at end,
          scheduled_payment_id = case when v_plan.scheduled_payment_id is null then null else cp.scheduled_payment_id end,
          updated_at = now()
    where cp.company_id = p_company_id;
  end if;

  update public.payments p
    set activate_auto_renew = p_enabled and p.recurring_mandate_activated
  where p.company_id = p_company_id
    and p.is_recurring = false
    and p.scheduled_change_kind = 'paid_downgrade'
    and (
      p.status = 'pending'
      or p.id = v_plan.scheduled_payment_id
    );

  return query
  select
    cp.company_id,
    cp.current_plan,
    cp.auto_renew,
    cp.scheduled_plan,
    cp.scheduled_plan_effective_at,
    cp.scheduled_payment_id
  from public.company_plans cp
  where cp.company_id = p_company_id;
end;
$$;

revoke all on function public.set_company_plan_auto_renew(uuid, boolean) from public, anon, authenticated;
grant execute on function public.set_company_plan_auto_renew(uuid, boolean) to service_role;

create or replace function public.finalize_robokassa_payment(
  p_inv_id integer,
  p_provider_id text,
  p_completed_at timestamptz default now()
)
returns table (
  payment_id uuid,
  company_id uuid,
  plan text,
  credits_granted integer,
  already_completed boolean
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_payment public.payments;
  v_company_plan public.company_plans;
  v_completed_at timestamptz;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_credits integer;
  v_existing_scheduled_plan text;
  v_existing_scheduled_effective_at timestamptz;
  v_clear_scheduled boolean := false;
  v_company_plan_found boolean := false;
  v_is_paid_scheduled_downgrade boolean := false;
  v_is_immediate_checkout boolean := false;
  v_defer_plan_activation boolean := false;
  v_granted_credits integer := 0;
  v_current_plan_weight integer := 0;
  v_payment_plan_weight integer := 0;
  v_company_plan_active boolean := false;
  v_recurring_mandate_activated boolean := false;
  v_recurring_mandate_inv_id text := null;
begin
  select *
    into v_payment
  from public.payments
  where inv_id = p_inv_id
  for update;

  if not found then
    raise exception 'PAYMENT_NOT_FOUND';
  end if;

  if v_payment.status = 'completed' then
    return query
    select v_payment.id, v_payment.company_id, v_payment.plan, coalesce(v_payment.credits_granted, 0), true;
    return;
  end if;

  if v_payment.status = 'requires_review' then
    return query
    select v_payment.id, v_payment.company_id, v_payment.plan, 0, true;
    return;
  end if;

  v_completed_at := coalesce(p_completed_at, now());

  if v_payment.status = 'failed'
    and v_payment.fail_reason = 'EXPIRED'
    and v_payment.checkout_expires_at is not null
    and v_payment.is_recurring = false
    and v_payment.scheduled_change_kind is null
  then
    update public.payments
      set status = 'requires_review',
          completed_at = v_completed_at,
          provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
          credits_granted = 0,
          fail_reason = 'CHECKOUT_EXPIRED_REQUIRES_REVIEW'
    where id = v_payment.id;

    return query
    select v_payment.id, v_payment.company_id, v_payment.plan, 0, false;
    return;
  end if;

  if v_payment.status <> 'pending' then
    raise exception 'PAYMENT_NOT_PENDING';
  end if;

  v_credits := case
    when v_payment.plan = 'starter' then 500
    when v_payment.plan = 'professional' then 2000
    else 0
  end;

  v_period_start := coalesce(v_payment.period_start, v_payment.scheduled_activation_at, now());
  v_period_end := coalesce(v_payment.period_end, v_period_start + interval '1 month');
  v_is_paid_scheduled_downgrade := v_payment.scheduled_change_kind = 'paid_downgrade';
  v_is_immediate_checkout := v_payment.is_recurring = false and v_payment.scheduled_change_kind is null;

  select *
    into v_company_plan
  from public.company_plans cp
  where cp.company_id = v_payment.company_id
  for update;
  v_company_plan_found := found;

  if v_is_immediate_checkout then
    if v_payment.checkout_expires_at is not null and v_completed_at > v_payment.checkout_expires_at then
      update public.payments
        set status = 'requires_review',
            completed_at = v_completed_at,
            provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
            credits_granted = 0,
            failed_at = v_completed_at,
            fail_reason = 'CHECKOUT_EXPIRED_REQUIRES_REVIEW'
      where id = v_payment.id;

      return query
      select v_payment.id, v_payment.company_id, v_payment.plan, 0, false;
      return;
    end if;

    if v_company_plan_found then
      v_current_plan_weight := case v_company_plan.current_plan
        when 'trial' then 0
        when 'starter' then 1
        when 'professional' then 2
        when 'enterprise' then 3
        else 0
      end;
      v_payment_plan_weight := case v_payment.plan
        when 'starter' then 1
        when 'professional' then 2
        when 'enterprise' then 3
        else 0
      end;
      v_company_plan_active := v_company_plan.current_plan = 'enterprise'
        or v_company_plan.period_end is null
        or v_company_plan.period_end > v_completed_at;

      if v_company_plan.current_plan = 'enterprise'
        or (v_company_plan_active and v_current_plan_weight > v_payment_plan_weight)
      then
        update public.payments
          set status = 'requires_review',
              completed_at = v_completed_at,
              provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
              credits_granted = 0,
              failed_at = v_completed_at,
              fail_reason = case
                when v_company_plan.current_plan = 'enterprise' then 'ENTERPRISE_REQUIRES_REVIEW'
                else 'ACTIVE_DOWNGRADE_REQUIRES_REVIEW'
              end
        where id = v_payment.id;

        return query
        select v_payment.id, v_payment.company_id, v_payment.plan, 0, false;
        return;
      end if;
    end if;

    v_period_start := v_completed_at;
    v_period_end := v_period_start + interval '1 month';
  end if;

  if v_is_paid_scheduled_downgrade then
    if not v_company_plan_found
      or v_payment.plan <> 'starter'
      or v_payment.scheduled_source_plan <> 'professional'
      or v_payment.scheduled_source_period_end is null
      or v_payment.scheduled_activation_at is null
      or v_company_plan.current_plan is distinct from v_payment.scheduled_source_plan
      or v_company_plan.period_end is distinct from v_payment.scheduled_source_period_end
    then
      update public.payments
        set status = 'requires_review',
            completed_at = v_completed_at,
            provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
            credits_granted = 0,
            failed_at = v_completed_at,
            fail_reason = 'STALE_SCHEDULED_PAYMENT_REQUIRES_REVIEW'
      where id = v_payment.id;

      return query
      select v_payment.id, v_payment.company_id, v_payment.plan, 0, false;
      return;
    end if;

    v_period_start := v_payment.scheduled_activation_at;
    v_period_end := coalesce(v_payment.period_end, v_period_start + interval '1 month');

    if v_completed_at < v_payment.scheduled_source_period_end
      and v_payment.scheduled_activation_at > v_completed_at
    then
      v_defer_plan_activation := true;
    elsif v_completed_at >= v_payment.scheduled_source_period_end then
      v_period_start := v_completed_at;
      v_period_end := v_period_start + interval '1 month';
    end if;
  end if;

  if v_defer_plan_activation
    and v_company_plan.scheduled_payment_id is not null
    and v_company_plan.scheduled_payment_id <> v_payment.id
  then
    raise exception 'PAID_SCHEDULE_EXISTS';
  end if;

  v_granted_credits := case when v_defer_plan_activation then 0 else v_credits end;
  v_recurring_mandate_activated := v_payment.recurring_mandate_activated or v_payment.is_recurring;
  v_recurring_mandate_inv_id := case
    when v_recurring_mandate_activated and v_payment.is_recurring = true and v_payment.parent_inv_id is not null then v_payment.parent_inv_id::text
    when v_recurring_mandate_activated and v_payment.is_recurring = false and coalesce(v_payment.activate_auto_renew, false) = true then p_inv_id::text
    else null
  end;

  update public.payments
    set status = 'completed',
        completed_at = v_completed_at,
        provider_id = coalesce(nullif(trim(p_provider_id), ''), provider_id, p_inv_id::text),
        credits_granted = coalesce(v_payment.credits_granted, v_granted_credits),
        period_start = v_period_start,
        period_end = v_period_end,
        recurring_mandate_activated = v_recurring_mandate_activated,
        failed_at = null,
        fail_reason = null
  where id = v_payment.id;

  if v_defer_plan_activation then
    update public.company_plans cp
      set scheduled_plan = v_payment.plan,
          scheduled_plan_effective_at = v_period_start,
          scheduled_payment_id = v_payment.id,
          updated_at = now()
    where cp.company_id = v_payment.company_id;

    return query
    select v_payment.id, v_payment.company_id, v_payment.plan, 0, false;
    return;
  end if;

  if v_company_plan_found then
    v_existing_scheduled_plan := v_company_plan.scheduled_plan;
    v_existing_scheduled_effective_at := v_company_plan.scheduled_plan_effective_at;
    v_clear_scheduled := v_existing_scheduled_plan is not null
      and (
        v_existing_scheduled_plan = v_payment.plan
        or (v_existing_scheduled_effective_at is not null and v_existing_scheduled_effective_at <= v_period_start)
      );

    update public.company_plans cp
      set current_plan = v_payment.plan,
          trial_expires_at = null,
          period_start = v_period_start,
          period_end = v_period_end,
          expires_at = v_period_end,
          robokassa_inv_id = p_inv_id::text,
          recurring_mandate_inv_id = v_recurring_mandate_inv_id,
          auto_renew = coalesce(v_payment.activate_auto_renew, false) and v_recurring_mandate_activated,
          scheduled_plan = case when v_clear_scheduled then null else cp.scheduled_plan end,
          scheduled_plan_effective_at = case when v_clear_scheduled then null else cp.scheduled_plan_effective_at end,
          scheduled_payment_id = case when v_clear_scheduled then null else cp.scheduled_payment_id end,
          updated_at = now()
    where cp.company_id = v_payment.company_id;
  else
    insert into public.company_plans (
      company_id,
      current_plan,
      period_start,
      period_end,
      expires_at,
      robokassa_inv_id,
      recurring_mandate_inv_id,
      auto_renew,
      scheduled_plan,
      scheduled_plan_effective_at,
      scheduled_payment_id
    )
    values (
      v_payment.company_id,
      v_payment.plan,
      v_period_start,
      v_period_end,
      v_period_end,
      p_inv_id::text,
      v_recurring_mandate_inv_id,
      coalesce(v_payment.activate_auto_renew, false) and v_recurring_mandate_activated,
      null,
      null,
      null
    )
    on conflict (company_id) do update
      set current_plan = excluded.current_plan,
          period_start = excluded.period_start,
          period_end = excluded.period_end,
          expires_at = excluded.expires_at,
          robokassa_inv_id = excluded.robokassa_inv_id,
          recurring_mandate_inv_id = excluded.recurring_mandate_inv_id,
          auto_renew = excluded.auto_renew,
          scheduled_plan = null,
          scheduled_plan_effective_at = null,
          scheduled_payment_id = null,
          updated_at = now();
  end if;

  if v_credits > 0 then
    insert into public.credit_ledger (
      company_id,
      delta,
      reason,
      reference_type,
      reference_id,
      notes
    )
    values (
      v_payment.company_id,
      v_credits,
      'grant',
      'plan_payment',
      v_payment.id,
      format('Plan payment inv_id=%s plan=%s', p_inv_id, v_payment.plan)
    )
    on conflict do nothing;
  end if;

  return query
  select v_payment.id, v_payment.company_id, v_payment.plan, v_credits, false;
end;
$$;

revoke all on function public.finalize_robokassa_payment(integer, text, timestamptz) from public, anon, authenticated;
grant execute on function public.finalize_robokassa_payment(integer, text, timestamptz) to service_role;

create or replace function public.activate_due_scheduled_plan_payments(
  p_now timestamptz default now(),
  p_company_id uuid default null
)
returns table (
  company_id uuid,
  payment_id uuid,
  plan text,
  credits_granted integer
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_row record;
  v_period_start timestamptz;
  v_period_end timestamptz;
  v_credits integer;
  v_recurring_mandate_inv_id text;
begin
  for v_row in
    select
      cp.company_id,
      cp.scheduled_plan,
      cp.scheduled_plan_effective_at,
      cp.recurring_mandate_inv_id as current_recurring_mandate_inv_id,
      p.id as payment_id,
      p.plan as payment_plan,
      p.inv_id,
      p.period_start,
      p.period_end,
      p.activate_auto_renew,
      p.recurring_mandate_activated
    from public.company_plans cp
    join public.payments p on p.id = cp.scheduled_payment_id
    where cp.scheduled_payment_id is not null
      and (p_company_id is null or cp.company_id = p_company_id)
      and cp.scheduled_plan is not null
      and cp.scheduled_plan_effective_at is not null
      and cp.scheduled_plan_effective_at <= p_now
      and p.status = 'completed'
      and p.plan = cp.scheduled_plan
    for update of cp, p
  loop
    v_period_start := coalesce(v_row.period_start, v_row.scheduled_plan_effective_at);
    v_period_end := coalesce(v_row.period_end, v_period_start + interval '1 month');
    v_credits := case
      when v_row.payment_plan = 'starter' then 500
      when v_row.payment_plan = 'professional' then 2000
      else 0
    end;
    v_recurring_mandate_inv_id := case
      when coalesce(v_row.activate_auto_renew, false) = true and v_row.recurring_mandate_activated = true then v_row.inv_id::text
      else null
    end;

    update public.company_plans cp
      set current_plan = v_row.payment_plan,
          trial_expires_at = null,
          period_start = v_period_start,
          period_end = v_period_end,
          expires_at = v_period_end,
          robokassa_inv_id = v_row.inv_id::text,
          recurring_mandate_inv_id = v_recurring_mandate_inv_id,
          auto_renew = coalesce(v_row.activate_auto_renew, false) and v_row.recurring_mandate_activated,
          scheduled_plan = null,
          scheduled_plan_effective_at = null,
          scheduled_payment_id = null,
          updated_at = now()
    where cp.company_id = v_row.company_id;

    update public.payments p
      set credits_granted = v_credits
    where p.id = v_row.payment_id
      and coalesce(p.credits_granted, 0) = 0;

    if v_credits > 0 then
      insert into public.credit_ledger (
        company_id,
        delta,
        reason,
        reference_type,
        reference_id,
        notes
      )
      values (
        v_row.company_id,
        v_credits,
        'grant',
        'plan_payment',
        v_row.payment_id,
        format('Plan payment inv_id=%s plan=%s', v_row.inv_id, v_row.payment_plan)
      )
      on conflict do nothing;
    end if;

    return query
    select v_row.company_id, v_row.payment_id, v_row.payment_plan, v_credits;
  end loop;
end;
$$;

revoke all on function public.activate_due_scheduled_plan_payments(timestamptz, uuid) from public, anon, authenticated;
grant execute on function public.activate_due_scheduled_plan_payments(timestamptz, uuid) to service_role;


-- ------------------------------------------------------------------
-- Source: supabase/sql/billing_recurring_root_mandate_invoice_overload_cleanup_v1.sql
-- ------------------------------------------------------------------
-- Billing recurring root mandate invoice overload cleanup v1
--
-- Keep only the scoped two-argument activate_due_scheduled_plan_payments RPC.
-- The old one-argument overload can make Supabase RPC calls with p_now
-- ambiguous and does not know about recurring_mandate_inv_id.

drop function if exists public.activate_due_scheduled_plan_payments(timestamptz);


-- ------------------------------------------------------------------
-- Source: supabase/sql/billing_recurring_root_mandate_enterprise_clear_v1.sql
-- ------------------------------------------------------------------
-- Billing recurring root mandate Enterprise clear v1
--
-- Keep the new recurring_mandate_inv_id field aligned with Enterprise
-- qualification, which already clears Robokassa billing state.

create or replace function public.qualify_company_enterprise_plan(
  p_company_id uuid,
  p_reason text default 'ENTERPRISE_SUPERSEDE'
)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_plan public.company_plans;
begin
  select *
    into v_plan
  from public.company_plans cp
  where cp.company_id = p_company_id
  for update;

  if not found then
    insert into public.company_plans (
      company_id,
      current_plan,
      trial_expires_at,
      intended_plan,
      expires_at,
      period_start,
      period_end,
      robokassa_inv_id,
      recurring_mandate_inv_id,
      auto_renew,
      scheduled_plan,
      scheduled_plan_effective_at,
      scheduled_payment_id
    )
    values (
      p_company_id,
      'enterprise',
      null,
      null,
      null,
      null,
      null,
      null,
      null,
      false,
      null,
      null,
      null
    );
    return true;
  end if;

  if v_plan.scheduled_payment_id is not null then
    update public.payments p
      set status = 'requires_review',
          failed_at = coalesce(p.failed_at, now()),
          fail_reason = coalesce(nullif(trim(p_reason), ''), 'ENTERPRISE_SUPERSEDE')
    where p.id = v_plan.scheduled_payment_id
      and p.status in ('pending', 'completed', 'requires_review');
  end if;

  update public.company_plans cp
    set current_plan = 'enterprise',
        trial_expires_at = null,
        intended_plan = null,
        expires_at = null,
        period_start = null,
        period_end = null,
        robokassa_inv_id = null,
        recurring_mandate_inv_id = null,
        auto_renew = false,
        scheduled_plan = null,
        scheduled_plan_effective_at = null,
        scheduled_payment_id = null,
        updated_at = now()
  where cp.company_id = p_company_id;

  return true;
end;
$$;

revoke all on function public.qualify_company_enterprise_plan(uuid, text) from public, anon, authenticated;
grant execute on function public.qualify_company_enterprise_plan(uuid, text) to service_role;


-- ------------------------------------------------------------------
-- Source: supabase/sql/enterprise_billing_flow_v1.sql
-- ------------------------------------------------------------------
-- Enterprise billing flow v1
-- Separates authenticated company plan-change requests, Enterprise agreements,
-- and manual invoices from external sales leads and Starter/Professional checkout.

create table if not exists public.billing_plan_change_requests (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies(id) on delete cascade,
  requested_by uuid not null references public.profiles(id) on delete restrict,
  current_plan text not null check (current_plan in ('trial', 'starter', 'professional', 'enterprise')),
  target_plan text not null check (target_plan in ('starter', 'professional', 'enterprise')),
  request_kind text not null check (
    request_kind in ('upgrade_to_enterprise', 'enterprise_exit', 'enterprise_terms_change', 'manual_plan_change')
  ),
  source text not null check (source in ('landing', 'settings', 'admin')),
  status text not null default 'submitted' check (
    status in ('submitted', 'in_review', 'contacted', 'approved', 'applied', 'rejected', 'canceled')
  ),
  user_message text,
  admin_note text,
  public_response text,
  handled_by uuid references public.profiles(id) on delete set null,
  handled_at timestamptz,
  approved_at timestamptz,
  applied_at timestamptz,
  rejected_at timestamptz,
  canceled_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index if not exists idx_billing_plan_change_requests_one_active_per_company
  on public.billing_plan_change_requests(company_id)
  where status in ('submitted', 'in_review', 'contacted', 'approved');

create index if not exists idx_billing_plan_change_requests_status_created_at
  on public.billing_plan_change_requests(status, created_at desc);

create table if not exists public.enterprise_agreements (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies(id) on delete cascade,
  source_request_id uuid references public.billing_plan_change_requests(id) on delete set null,
  status text not null default 'draft' check (status in ('draft', 'pending_payment', 'active', 'ended', 'canceled')),
  starts_at timestamptz not null,
  ends_at timestamptz,
  is_open_ended boolean not null default false,
  credits_limit integer check (credits_limit is null or credits_limit >= 0),
  terms_summary text,
  internal_note text,
  created_by uuid not null references public.profiles(id) on delete restrict,
  activated_by uuid references public.profiles(id) on delete set null,
  activated_at timestamptz,
  ended_by uuid references public.profiles(id) on delete set null,
  ended_at timestamptz,
  ended_reason text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (is_open_ended = true or ends_at is not null)
);

create unique index if not exists idx_enterprise_agreements_one_active_per_company
  on public.enterprise_agreements(company_id)
  where status = 'active';

create index if not exists idx_enterprise_agreements_company_created_at
  on public.enterprise_agreements(company_id, created_at desc);

create table if not exists public.billing_manual_invoices (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies(id) on delete cascade,
  request_id uuid references public.billing_plan_change_requests(id) on delete set null,
  agreement_id uuid references public.enterprise_agreements(id) on delete set null,
  provider text not null default 'robokassa' check (provider in ('robokassa')),
  provider_invoice_id text,
  provider_invoice_url text,
  provider_status text,
  amount integer not null check (amount > 0),
  currency text not null default 'RUB',
  description text not null,
  payer_email text,
  service_period_start timestamptz,
  service_period_end timestamptz,
  status text not null default 'draft' check (
    status in ('draft', 'issued', 'paid', 'expired', 'canceled', 'refunded', 'requires_review')
  ),
  fiscal_receipt jsonb,
  provider_payload jsonb,
  created_by uuid not null references public.profiles(id) on delete restrict,
  issued_at timestamptz,
  paid_at timestamptz,
  expires_at timestamptz,
  canceled_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index if not exists idx_billing_manual_invoices_provider_invoice_once
  on public.billing_manual_invoices(provider, provider_invoice_id)
  where provider_invoice_id is not null;

create index if not exists idx_billing_manual_invoices_company_created_at
  on public.billing_manual_invoices(company_id, created_at desc);

insert into public.enterprise_agreements (
  company_id,
  status,
  starts_at,
  ends_at,
  is_open_ended,
  terms_summary,
  created_by,
  activated_at
)
select
  cp.company_id,
  'active',
  coalesce(cp.updated_at, now()),
  null,
  true,
  'Backfilled active Enterprise access',
  p.id,
  coalesce(cp.updated_at, now())
from public.company_plans cp
join lateral (
  select pr.id
  from public.platform_admins pa
  join public.profiles pr on pr.id = pa.user_id
  order by pa.created_at asc
  limit 1
) p on true
where cp.current_plan = 'enterprise'
  and not exists (
    select 1
    from public.enterprise_agreements ea
    where ea.company_id = cp.company_id
      and ea.status = 'active'
  );

alter table public.billing_plan_change_requests enable row level security;
alter table public.enterprise_agreements enable row level security;
alter table public.billing_manual_invoices enable row level security;


-- ------------------------------------------------------------------
-- Source: supabase/sql/enterprise_manual_invoice_inv_id_v1.sql
-- ------------------------------------------------------------------
-- Enterprise manual invoice Robokassa InvId v1
--
-- Manual Enterprise invoices use their own high-range Robokassa InvId values.
-- This keeps Invoice API callbacks routable by InvId while avoiding collisions
-- with the Starter/Professional payments_inv_id_seq in normal operation.

create sequence if not exists public.billing_manual_invoice_inv_id_seq
  as integer
  start with 1000000000
  increment by 1
  minvalue 1000000000
  maxvalue 2147483647
  cache 1;

alter table public.billing_manual_invoices
  alter column provider_invoice_id set default nextval('public.billing_manual_invoice_inv_id_seq')::text;


-- ------------------------------------------------------------------
-- Source: supabase/sql/enterprise_agreement_activation_rpc_v1.sql
-- ------------------------------------------------------------------
-- Enterprise agreement activation/end RPC v1
--
-- Keep Enterprise agreement lifecycle and company_plans changes atomic.
-- Apply through Supabase MCP after verifying the hiiire project.

create or replace function public.activate_enterprise_agreement(
  p_agreement_id uuid,
  p_actor_id uuid,
  p_reason text default 'ENTERPRISE_AGREEMENT_ACTIVATED'
)
returns table (
  agreement_id uuid,
  company_id uuid,
  status text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_agreement public.enterprise_agreements;
  v_plan public.company_plans;
  v_has_plan boolean := false;
  v_now timestamptz := now();
  v_reason text := coalesce(nullif(trim(p_reason), ''), 'ENTERPRISE_AGREEMENT_ACTIVATED');
begin
  select *
    into v_agreement
  from public.enterprise_agreements ea
  where ea.id = p_agreement_id
  for update;

  if not found then
    raise exception 'AGREEMENT_NOT_FOUND';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_agreement.company_id::text, 0));

  if v_agreement.status in ('draft', 'pending_payment') then
    null;
  else
    raise exception 'AGREEMENT_NOT_ACTIVATABLE';
  end if;

  if v_agreement.starts_at is null then
    raise exception 'STARTS_AT_INVALID';
  end if;

  if not v_agreement.is_open_ended and v_agreement.ends_at is null then
    raise exception 'ENDS_AT_REQUIRED';
  end if;

  if not v_agreement.is_open_ended and v_agreement.ends_at <= v_agreement.starts_at then
    raise exception 'ENDS_AT_MUST_BE_AFTER_STARTS_AT';
  end if;

  if v_agreement.credits_limit is not null and v_agreement.credits_limit < 0 then
    raise exception 'CREDITS_LIMIT_INVALID';
  end if;

  if nullif(trim(coalesce(v_agreement.terms_summary, '')), '') is null then
    raise exception 'TERMS_SUMMARY_REQUIRED';
  end if;

  -- The partial unique index idx_enterprise_agreements_one_active_per_company
  -- also protects this invariant; the explicit check keeps API errors stable.
  if exists (
    select 1
    from public.enterprise_agreements ea
    where ea.company_id = v_agreement.company_id
      and ea.status = 'active'
      and ea.id <> v_agreement.id
  ) then
    raise exception 'ACTIVE_AGREEMENT_EXISTS';
  end if;

  select *
    into v_plan
  from public.company_plans cp
  where cp.company_id = v_agreement.company_id
  for update;
  v_has_plan := found;

  if v_has_plan and v_plan.scheduled_payment_id is not null then
    update public.payments p
      set status = 'requires_review',
          failed_at = coalesce(p.failed_at, v_now),
          fail_reason = coalesce(nullif(trim(v_reason), ''), 'ENTERPRISE_AGREEMENT_ACTIVATED')
    where p.id = v_plan.scheduled_payment_id
      and p.status in ('pending', 'completed', 'requires_review');
  end if;

  if v_has_plan then
    update public.company_plans cp
      set current_plan = 'enterprise',
          trial_expires_at = null,
          intended_plan = null,
          expires_at = null,
          period_start = null,
          period_end = null,
          robokassa_inv_id = null,
          recurring_mandate_inv_id = null,
          auto_renew = false,
          scheduled_plan = null,
          scheduled_plan_effective_at = null,
          scheduled_payment_id = null,
          updated_at = v_now
    where cp.company_id = v_agreement.company_id;
  else
    insert into public.company_plans (
      company_id,
      current_plan,
      trial_expires_at,
      intended_plan,
      expires_at,
      period_start,
      period_end,
      robokassa_inv_id,
      recurring_mandate_inv_id,
      auto_renew,
      scheduled_plan,
      scheduled_plan_effective_at,
      scheduled_payment_id,
      updated_at
    )
    values (
      v_agreement.company_id,
      'enterprise',
      null,
      null,
      null,
      null,
      null,
      null,
      null,
      false,
      null,
      null,
      null,
      v_now
    );
  end if;

  update public.enterprise_agreements ea
    set status = 'active',
        activated_by = p_actor_id,
        activated_at = v_now,
        updated_at = v_now
  where ea.id = v_agreement.id;

  if v_agreement.source_request_id is not null then
    update public.billing_plan_change_requests bpr
      set status = 'applied',
          handled_by = p_actor_id,
          handled_at = v_now,
          applied_at = v_now,
          updated_at = v_now
    where bpr.id = v_agreement.source_request_id
      and bpr.status in ('submitted', 'in_review', 'contacted', 'approved');
  end if;

  return query
    select v_agreement.id, v_agreement.company_id, 'active'::text;
end;
$$;

create or replace function public.end_enterprise_agreement(
  p_agreement_id uuid,
  p_actor_id uuid,
  p_reason text,
  p_target_plan text default null
)
returns table (
  agreement_id uuid,
  company_id uuid,
  status text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_agreement public.enterprise_agreements;
  v_plan public.company_plans;
  v_has_plan boolean := false;
  v_now timestamptz := now();
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_target_plan text := nullif(trim(coalesce(p_target_plan, '')), '');
begin
  select *
    into v_agreement
  from public.enterprise_agreements ea
  where ea.id = p_agreement_id
  for update;

  if not found then
    raise exception 'AGREEMENT_NOT_FOUND';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_agreement.company_id::text, 0));

  if v_agreement.status <> 'active' then
    raise exception 'AGREEMENT_NOT_ACTIVE';
  end if;

  if v_reason is null then
    raise exception 'END_REASON_REQUIRED';
  end if;

  if v_target_plan is not null and v_target_plan not in ('starter', 'professional') then
    raise exception 'TARGET_PLAN_INVALID';
  end if;

  update public.enterprise_agreements ea
    set status = 'ended',
        ended_by = p_actor_id,
        ended_at = v_now,
        ended_reason = v_reason,
        updated_at = v_now
  where ea.id = v_agreement.id
    and ea.status = 'active';

  if v_target_plan is not null then
    select *
      into v_plan
    from public.company_plans cp
    where cp.company_id = v_agreement.company_id
    for update;
    v_has_plan := found;

    if v_has_plan and v_plan.scheduled_payment_id is not null then
      update public.payments p
        set status = 'requires_review',
            failed_at = coalesce(p.failed_at, v_now),
            fail_reason = coalesce(p.fail_reason, 'ENTERPRISE_AGREEMENT_ENDED')
      where p.id = v_plan.scheduled_payment_id
        and p.status in ('pending', 'completed', 'requires_review');
    end if;

    if v_has_plan then
      update public.company_plans cp
        set current_plan = v_target_plan,
            intended_plan = v_target_plan,
            trial_expires_at = null,
            expires_at = null,
            period_start = null,
            period_end = null,
            robokassa_inv_id = null,
            recurring_mandate_inv_id = null,
            auto_renew = false,
            scheduled_plan = null,
            scheduled_plan_effective_at = null,
            scheduled_payment_id = null,
            updated_at = v_now
      where cp.company_id = v_agreement.company_id;
    else
      insert into public.company_plans (
        company_id,
        current_plan,
        intended_plan,
        trial_expires_at,
        expires_at,
        period_start,
        period_end,
        robokassa_inv_id,
        recurring_mandate_inv_id,
        auto_renew,
        scheduled_plan,
        scheduled_plan_effective_at,
        scheduled_payment_id,
        updated_at
      )
      values (
        v_agreement.company_id,
        v_target_plan,
        v_target_plan,
        null,
        null,
        null,
        null,
        null,
        null,
        false,
        null,
        null,
        null,
        v_now
      );
    end if;
  end if;

  return query
    select v_agreement.id, v_agreement.company_id, 'ended'::text;
end;
$$;

revoke all on function public.activate_enterprise_agreement(uuid, uuid, text) from public, anon, authenticated;
grant execute on function public.activate_enterprise_agreement(uuid, uuid, text) to service_role;

revoke all on function public.end_enterprise_agreement(uuid, uuid, text, text) from public, anon, authenticated;
grant execute on function public.end_enterprise_agreement(uuid, uuid, text, text) to service_role;


-- ------------------------------------------------------------------
-- Source: supabase/sql/enterprise_agreement_amendments_and_request_closure_v1.sql
-- ------------------------------------------------------------------
-- Enterprise agreement amendments and request closure v1
--
-- Adds immutable amendment linkage and request-aware Enterprise exit closure.
-- Create/apply through Supabase MCP after verifying the hiiire project.

alter table public.enterprise_agreements
  add column if not exists replaces_agreement_id uuid
    references public.enterprise_agreements(id) on delete set null;

create index if not exists idx_enterprise_agreements_replaces_agreement_id
  on public.enterprise_agreements(replaces_agreement_id)
  where replaces_agreement_id is not null;

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'enterprise_agreements_no_self_replace'
      and conrelid = 'public.enterprise_agreements'::regclass
  ) then
    alter table public.enterprise_agreements
      add constraint enterprise_agreements_no_self_replace
      check (replaces_agreement_id is null or replaces_agreement_id <> id);
  end if;
end;
$$;

create or replace function public.activate_enterprise_agreement(
  p_agreement_id uuid,
  p_actor_id uuid,
  p_reason text default 'ENTERPRISE_AGREEMENT_ACTIVATED'
)
returns table (
  agreement_id uuid,
  company_id uuid,
  status text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_agreement public.enterprise_agreements;
  v_replaced_agreement public.enterprise_agreements;
  v_source_request public.billing_plan_change_requests;
  v_plan public.company_plans;
  v_has_plan boolean := false;
  v_source_request_applied_count integer := 0;
  v_now timestamptz := now();
  v_reason text := coalesce(nullif(trim(p_reason), ''), 'ENTERPRISE_AGREEMENT_ACTIVATED');
begin
  select *
    into v_agreement
  from public.enterprise_agreements ea
  where ea.id = p_agreement_id
  for update;

  if not found then
    raise exception 'AGREEMENT_NOT_FOUND';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_agreement.company_id::text, 0));

  if v_agreement.status in ('draft', 'pending_payment') then
    null;
  else
    raise exception 'AGREEMENT_NOT_ACTIVATABLE';
  end if;

  if v_agreement.starts_at is null then
    raise exception 'STARTS_AT_INVALID';
  end if;

  if not v_agreement.is_open_ended and v_agreement.ends_at is null then
    raise exception 'ENDS_AT_REQUIRED';
  end if;

  if not v_agreement.is_open_ended and v_agreement.ends_at <= v_agreement.starts_at then
    raise exception 'ENDS_AT_MUST_BE_AFTER_STARTS_AT';
  end if;

  if v_agreement.credits_limit is not null and v_agreement.credits_limit < 0 then
    raise exception 'CREDITS_LIMIT_INVALID';
  end if;

  if nullif(trim(coalesce(v_agreement.terms_summary, '')), '') is null then
    raise exception 'TERMS_SUMMARY_REQUIRED';
  end if;

  if v_agreement.source_request_id is null then
    raise exception 'SOURCE_REQUEST_REQUIRED';
  end if;

  if v_agreement.replaces_agreement_id is not null then
    if v_agreement.source_request_id is null then
      raise exception 'SOURCE_REQUEST_REQUIRED';
    end if;

    select *
      into v_replaced_agreement
    from public.enterprise_agreements ea
    where ea.id = v_agreement.replaces_agreement_id
    for update;

    if not found then
      raise exception 'REPLACED_AGREEMENT_NOT_FOUND';
    end if;

    if v_replaced_agreement.company_id <> v_agreement.company_id then
      raise exception 'REPLACED_AGREEMENT_COMPANY_MISMATCH';
    end if;

    if v_replaced_agreement.status <> 'active' then
      raise exception 'REPLACED_AGREEMENT_NOT_ACTIVE';
    end if;
  end if;

  -- The partial unique index idx_enterprise_agreements_one_active_per_company
  -- also protects this invariant; the explicit check keeps API errors stable.
  if exists (
    select 1
    from public.enterprise_agreements ea
    where ea.company_id = v_agreement.company_id
      and ea.status = 'active'
      and ea.id <> v_agreement.id
      and (
        v_agreement.replaces_agreement_id is null
        or ea.id <> v_agreement.replaces_agreement_id
      )
  ) then
    raise exception 'ACTIVE_AGREEMENT_EXISTS';
  end if;

  if v_agreement.source_request_id is not null then
    select *
      into v_source_request
    from public.billing_plan_change_requests bpr
    where bpr.id = v_agreement.source_request_id
    for update;

    if not found then
      raise exception 'SOURCE_REQUEST_NOT_FOUND';
    end if;

    if v_source_request.company_id <> v_agreement.company_id then
      raise exception 'SOURCE_REQUEST_COMPANY_MISMATCH';
    end if;

    if v_source_request.status <> 'approved' then
      raise exception 'SOURCE_REQUEST_STATUS_INVALID';
    end if;

    if v_source_request.target_plan <> 'enterprise' then
      raise exception 'SOURCE_REQUEST_TARGET_PLAN_INVALID';
    end if;

    if v_agreement.replaces_agreement_id is null then
      if v_source_request.request_kind <> 'upgrade_to_enterprise' then
        raise exception 'SOURCE_REQUEST_KIND_INVALID';
      end if;

      if v_source_request.current_plan = 'enterprise' then
        raise exception 'SOURCE_REQUEST_CURRENT_PLAN_INVALID';
      end if;
    else
      if v_source_request.request_kind <> 'enterprise_terms_change' then
        raise exception 'SOURCE_REQUEST_KIND_INVALID';
      end if;

      if v_source_request.current_plan <> 'enterprise' then
        raise exception 'SOURCE_REQUEST_CURRENT_PLAN_INVALID';
      end if;
    end if;
  end if;

  select *
    into v_plan
  from public.company_plans cp
  where cp.company_id = v_agreement.company_id
  for update;
  v_has_plan := found;

  if v_has_plan and v_plan.scheduled_payment_id is not null then
    update public.payments p
      set status = 'requires_review',
          failed_at = coalesce(p.failed_at, v_now),
          fail_reason = coalesce(nullif(trim(v_reason), ''), 'ENTERPRISE_AGREEMENT_ACTIVATED')
    where p.id = v_plan.scheduled_payment_id
      and p.status in ('pending', 'completed', 'requires_review');
  end if;

  if v_agreement.replaces_agreement_id is not null then
    update public.enterprise_agreements ea
      set status = 'ended',
          ended_by = p_actor_id,
          ended_at = v_now,
          ended_reason = v_reason,
          updated_at = v_now
    where ea.id = v_replaced_agreement.id
      and ea.status = 'active';
  end if;

  if v_has_plan then
    update public.company_plans cp
      set current_plan = 'enterprise',
          trial_expires_at = null,
          intended_plan = null,
          expires_at = null,
          period_start = null,
          period_end = null,
          robokassa_inv_id = null,
          recurring_mandate_inv_id = null,
          auto_renew = false,
          scheduled_plan = null,
          scheduled_plan_effective_at = null,
          scheduled_payment_id = null,
          updated_at = v_now
    where cp.company_id = v_agreement.company_id;
  else
    insert into public.company_plans (
      company_id,
      current_plan,
      trial_expires_at,
      intended_plan,
      expires_at,
      period_start,
      period_end,
      robokassa_inv_id,
      recurring_mandate_inv_id,
      auto_renew,
      scheduled_plan,
      scheduled_plan_effective_at,
      scheduled_payment_id,
      updated_at
    )
    values (
      v_agreement.company_id,
      'enterprise',
      null,
      null,
      null,
      null,
      null,
      null,
      null,
      false,
      null,
      null,
      null,
      v_now
    );
  end if;

  update public.enterprise_agreements ea
    set status = 'active',
        activated_by = p_actor_id,
        activated_at = v_now,
        updated_at = v_now
  where ea.id = v_agreement.id;

  if v_agreement.source_request_id is not null then
    update public.billing_plan_change_requests bpr
      set status = 'applied',
          handled_by = p_actor_id,
          handled_at = v_now,
          applied_at = v_now,
          updated_at = v_now
    where bpr.id = v_agreement.source_request_id
      and bpr.status = 'approved';

    get diagnostics v_source_request_applied_count = row_count;
    if v_source_request_applied_count <> 1 then
      raise exception 'SOURCE_REQUEST_APPLY_FAILED';
    end if;
  end if;

  return query
    select v_agreement.id, v_agreement.company_id, 'active'::text;
end;
$$;

drop function if exists public.end_enterprise_agreement(uuid, uuid, text, text);

create or replace function public.end_enterprise_agreement(
  p_agreement_id uuid,
  p_actor_id uuid,
  p_reason text,
  p_target_plan text default null,
  p_request_id uuid default null
)
returns table (
  agreement_id uuid,
  company_id uuid,
  status text
)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_agreement public.enterprise_agreements;
  v_request public.billing_plan_change_requests;
  v_plan public.company_plans;
  v_has_plan boolean := false;
  v_now timestamptz := now();
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
  v_target_plan text := nullif(trim(coalesce(p_target_plan, '')), '');
begin
  select *
    into v_agreement
  from public.enterprise_agreements ea
  where ea.id = p_agreement_id
  for update;

  if not found then
    raise exception 'AGREEMENT_NOT_FOUND';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(v_agreement.company_id::text, 0));

  if v_agreement.status <> 'active' then
    raise exception 'AGREEMENT_NOT_ACTIVE';
  end if;

  if v_reason is null then
    raise exception 'END_REASON_REQUIRED';
  end if;

  if p_request_id is not null then
    select *
      into v_request
    from public.billing_plan_change_requests bpr
    where bpr.id = p_request_id
    for update;

    if not found then
      raise exception 'REQUEST_NOT_FOUND';
    end if;

    if v_request.company_id <> v_agreement.company_id then
      raise exception 'REQUEST_COMPANY_MISMATCH';
    end if;

    if v_request.request_kind <> 'enterprise_exit' then
      raise exception 'REQUEST_KIND_INVALID';
    end if;

    if v_request.status <> 'approved' then
      raise exception 'REQUEST_STATUS_INVALID';
    end if;

    if v_request.current_plan <> 'enterprise' then
      raise exception 'REQUEST_CURRENT_PLAN_INVALID';
    end if;

    if v_request.target_plan not in ('starter', 'professional') then
      raise exception 'REQUEST_TARGET_PLAN_INVALID';
    end if;

    if v_target_plan is null then
      v_target_plan := v_request.target_plan;
    elsif v_target_plan <> v_request.target_plan then
      raise exception 'TARGET_PLAN_MISMATCH';
    end if;
  end if;

  if v_target_plan is not null and v_target_plan not in ('starter', 'professional') then
    raise exception 'TARGET_PLAN_INVALID';
  end if;

  update public.enterprise_agreements ea
    set status = 'ended',
        ended_by = p_actor_id,
        ended_at = v_now,
        ended_reason = v_reason,
        updated_at = v_now
  where ea.id = v_agreement.id
    and ea.status = 'active';

  if v_target_plan is not null then
    select *
      into v_plan
    from public.company_plans cp
    where cp.company_id = v_agreement.company_id
    for update;
    v_has_plan := found;

    if v_has_plan and v_plan.scheduled_payment_id is not null then
      update public.payments p
        set status = 'requires_review',
            failed_at = coalesce(p.failed_at, v_now),
            fail_reason = coalesce(p.fail_reason, 'ENTERPRISE_AGREEMENT_ENDED')
      where p.id = v_plan.scheduled_payment_id
        and p.status in ('pending', 'completed', 'requires_review');
    end if;

    if v_has_plan then
      update public.company_plans cp
        set current_plan = v_target_plan,
            intended_plan = v_target_plan,
            trial_expires_at = null,
            expires_at = null,
            period_start = null,
            period_end = null,
            robokassa_inv_id = null,
            recurring_mandate_inv_id = null,
            auto_renew = false,
            scheduled_plan = null,
            scheduled_plan_effective_at = null,
            scheduled_payment_id = null,
            updated_at = v_now
      where cp.company_id = v_agreement.company_id;
    else
      insert into public.company_plans (
        company_id,
        current_plan,
        intended_plan,
        trial_expires_at,
        expires_at,
        period_start,
        period_end,
        robokassa_inv_id,
        recurring_mandate_inv_id,
        auto_renew,
        scheduled_plan,
        scheduled_plan_effective_at,
        scheduled_payment_id,
        updated_at
      )
      values (
        v_agreement.company_id,
        v_target_plan,
        v_target_plan,
        null,
        null,
        null,
        null,
        null,
        null,
        false,
        null,
        null,
        null,
        v_now
      );
    end if;
  end if;

  if p_request_id is not null then
    update public.billing_plan_change_requests bpr
      set status = 'applied',
          handled_by = p_actor_id,
          handled_at = v_now,
          applied_at = v_now,
          updated_at = v_now
    where bpr.id = p_request_id;
  end if;

  return query
    select v_agreement.id, v_agreement.company_id, 'ended'::text;
end;
$$;

revoke all on function public.activate_enterprise_agreement(uuid, uuid, text) from public, anon, authenticated;
grant execute on function public.activate_enterprise_agreement(uuid, uuid, text) to service_role;

revoke all on function public.end_enterprise_agreement(uuid, uuid, text, text, uuid) from public, anon, authenticated;
