  on public.assistant_threads
  for select
  using (
    company_id = (select private.current_user_company_id())
    and (
      visibility = 'company'
      or owner_id = (select auth.uid())
      or exists (
        select 1
        from public.profiles p
        where p.id = (select auth.uid())
          and p.company_id = assistant_threads.company_id
          and p.role = 'admin'
