-- ------------------------------------------------------------------
-- Source: supabase/sql/marketing_attribution_admin_report_v6.sql
-- ------------------------------------------------------------------
drop function if exists public.get_marketing_admin_report(timestamptz, integer, integer);

create or replace function public.get_marketing_admin_report(
  p_start_at timestamptz,
  p_recent_limit integer default 50,
  p_source_limit integer default 200,
  p_recent_offset integer default 0
)
returns jsonb
language sql
set search_path = public
as $$
with
report_limits as (
  select greatest(1, least(coalesce(p_source_limit, 200), 500))::integer as source_limit
),
visit_groups as (
  select
    coalesce(nullif(first_utm_source, ''), 'direct') as source,
    coalesce(nullif(first_utm_medium, ''), 'none') as medium,
    coalesce(nullif(first_utm_campaign, ''), 'not set') as campaign,
    count(*)::integer as visits,
    count(distinct visitor_id)::integer as visitors
  from public.marketing_visit_events
  where seen_at >= p_start_at
  group by 1, 2, 3
),
conversion_groups as (
  select
    coalesce(nullif(first_utm_source, ''), 'direct') as source,
    coalesce(nullif(first_utm_medium, ''), 'none') as medium,
    coalesce(nullif(first_utm_campaign, ''), 'not set') as campaign,
    count(*)::integer as signups,
    count(distinct company_id) filter (where company_id is not null)::integer as companies
  from public.marketing_conversions
  where signed_up_at >= p_start_at
  group by 1, 2, 3
),
first_company_conversion as (
  select distinct on (company_id)
    company_id,
    first_utm_source,
    first_utm_medium,
    first_utm_campaign
  from public.marketing_conversions
  where company_id is not null
  order by company_id, signed_up_at asc
),
all_completed_payments as (
  select
    p.id::text as payment_id,
    p.company_id,
    p.amount::bigint as amount,
    p.completed_at
  from public.payments p
  where p.status = 'completed'
    and p.completed_at >= p_start_at
  union all
  select
    ctp.id::text as payment_id,
    ctp.company_id,
    ctp.amount::bigint as amount,
    ctp.completed_at
  from public.credit_topup_payments ctp
  where ctp.status = 'completed'
    and ctp.completed_at >= p_start_at
),
payment_groups as (
  select
    case when c.company_id is null then 'unattributed' else coalesce(nullif(c.first_utm_source, ''), 'direct') end as source,
    case when c.company_id is null then 'none' else coalesce(nullif(c.first_utm_medium, ''), 'none') end as medium,
    case when c.company_id is null then 'not set' else coalesce(nullif(c.first_utm_campaign, ''), 'not set') end as campaign,
    count(ap.payment_id)::integer as payments,
    coalesce(sum(ap.amount), 0)::bigint as revenue_kopecks
  from all_completed_payments ap
  left join first_company_conversion c on c.company_id = ap.company_id
  group by 1, 2, 3
),
source_keys as (
  select source, medium, campaign from visit_groups
  union
  select source, medium, campaign from conversion_groups
  union
  select source, medium, campaign from payment_groups
),
source_rows as (
  select
    concat(k.source, '||', k.medium, '||', k.campaign) as key,
    k.source,
    k.medium,
    k.campaign,
    coalesce(v.visits, 0) as visits,
    coalesce(v.visitors, 0) as visitors,
    coalesce(c.signups, 0) as signups,
    coalesce(c.companies, 0) as companies,
    coalesce(p.payments, 0) as payments,
    coalesce(p.revenue_kopecks, 0) as "revenueKopecks"
  from source_keys k
  left join visit_groups v using (source, medium, campaign)
  left join conversion_groups c using (source, medium, campaign)
  left join payment_groups p using (source, medium, campaign)
),
source_ranked as (
  select
    source_rows.*,
    row_number() over (order by "revenueKopecks" desc, signups desc, visits desc, key asc) as source_rank
  from source_rows
),
source_limited as (
  select key, source, medium, campaign, visits, visitors, signups, companies, payments, "revenueKopecks"
  from source_ranked, report_limits
  where source_rank <= report_limits.source_limit
),
source_other_keys as (
  select source, medium, campaign
  from source_ranked, report_limits
  where source_rank > report_limits.source_limit
),
source_other as (
  select
    'other||mixed||other' as key,
    'other' as source,
    'mixed' as medium,
    'other' as campaign,
    coalesce(sum(sr.visits), 0)::integer as visits,
    (
      select count(distinct visitor_id)::integer
      from public.marketing_visit_events e
      join source_other_keys k
        on k.source = coalesce(nullif(e.first_utm_source, ''), 'direct')
       and k.medium = coalesce(nullif(e.first_utm_medium, ''), 'none')
       and k.campaign = coalesce(nullif(e.first_utm_campaign, ''), 'not set')
      where e.seen_at >= p_start_at
    ) as visitors,
    coalesce(sum(sr.signups), 0)::integer as signups,
    coalesce(sum(sr.companies), 0)::integer as companies,
    coalesce(sum(sr.payments), 0)::integer as payments,
    coalesce(sum(sr."revenueKopecks"), 0)::bigint as "revenueKopecks"
  from source_ranked sr, report_limits
  where sr.source_rank > report_limits.source_limit
  having count(*) > 0
),
source_output as (
  select * from source_limited
  union all
  select * from source_other
),
recent_conversions as (
  select
    mc.user_id as "userId",
    mc.company_id as "companyId",
    mc.signed_up_at as "signedUpAt",
    coalesce(nullif(mc.first_utm_source, ''), 'direct') as source,
    coalesce(nullif(mc.first_utm_medium, ''), 'none') as medium,
    coalesce(nullif(mc.first_utm_campaign, ''), 'not set') as campaign,
    pr.name as "profileName",
    pr.email as "profileEmail",
    co.name as "companyName"
  from public.marketing_conversions mc
  left join public.profiles pr on pr.id = mc.user_id
  left join public.companies co on co.id = mc.company_id
  where mc.signed_up_at >= p_start_at
  order by mc.signed_up_at desc
  limit greatest(0, least(coalesce(p_recent_limit, 50), 200))
  offset greatest(0, coalesce(p_recent_offset, 0))
),
period_totals as (
  select
    (select count(*)::integer from public.marketing_visit_events where seen_at >= p_start_at) as visits,
    (select count(distinct visitor_id)::integer from public.marketing_visit_events where seen_at >= p_start_at) as visitors,
    (select count(*)::integer from public.marketing_conversions where signed_up_at >= p_start_at) as signups,
    (
      select count(distinct company_id)::integer
      from public.marketing_conversions
      where signed_up_at >= p_start_at and company_id is not null
    ) as companies,
    (select count(*)::integer from all_completed_payments) as payments,
    (select coalesce(sum(amount), 0)::bigint from all_completed_payments) as "revenueKopecks"
)
select jsonb_build_object(
  'totals',
  coalesce(
    (
      select jsonb_build_object(
        'visits', visits,
        'visitors', visitors,
        'signups', signups,
        'companies', companies,
        'payments', payments,
        'revenueKopecks', "revenueKopecks"
      )
      from period_totals
    ),
    jsonb_build_object('visits', 0, 'visitors', 0, 'signups', 0, 'companies', 0, 'payments', 0, 'revenueKopecks', 0)
  ),
  'sources',
  coalesce(
    (
      select jsonb_agg(to_jsonb(source_output) order by "revenueKopecks" desc, signups desc, visits desc, key asc)
      from source_output
    ),
    '[]'::jsonb
  ),
  'recentConversions',
  coalesce(
    (
      select jsonb_agg(to_jsonb(recent_conversions) order by "signedUpAt" desc)
      from recent_conversions
    ),
    '[]'::jsonb
  )
);
$$;

revoke all on function public.get_marketing_admin_report(timestamptz, integer, integer, integer) from public, anon, authenticated;
grant execute on function public.get_marketing_admin_report(timestamptz, integer, integer, integer) to service_role;


-- ------------------------------------------------------------------
-- Source: supabase/sql/first_ai_onboarding_state_v1.sql
-- ------------------------------------------------------------------
-- First AI analysis onboarding state.
-- User-scoped so each team member can independently complete or hide onboarding.

create table if not exists public.first_ai_onboarding_states (
  user_id uuid primary key references public.profiles(id) on delete cascade,
  started_path text null check (started_path in ('manual', 'hh')),
  completed_at timestamptz null,
  dismissed_at timestamptz null,
  result_opened_at timestamptz null,
  result_acknowledged_at timestamptz null,
  hh_oauth_error_at timestamptz null,
  hh_started_at timestamptz null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint first_ai_onboarding_single_terminal_state check (
    num_nonnulls(completed_at, dismissed_at) <= 1
  )
);

create index if not exists idx_first_ai_onboarding_states_updated_at
  on public.first_ai_onboarding_states (updated_at desc);

create or replace function public.record_first_ai_onboarding_open_result(
  p_user_id uuid,
  p_now timestamptz
) returns void
language sql
security definer
set search_path = public
as $$
  insert into public.first_ai_onboarding_states (user_id, result_opened_at, updated_at)
  values (p_user_id, p_now, p_now)
  on conflict (user_id) do update
  set
    result_opened_at = coalesce(public.first_ai_onboarding_states.result_opened_at, excluded.result_opened_at),
    updated_at = case
      when public.first_ai_onboarding_states.result_opened_at is null then excluded.updated_at
      else public.first_ai_onboarding_states.updated_at
    end
  where public.first_ai_onboarding_states.completed_at is null
    and public.first_ai_onboarding_states.dismissed_at is null;
$$;

revoke execute on function public.record_first_ai_onboarding_open_result(uuid, timestamptz) from public, anon, authenticated;
grant execute on function public.record_first_ai_onboarding_open_result(uuid, timestamptz) to service_role;

create or replace function public.record_first_ai_onboarding_acknowledge_result(
  p_user_id uuid,
  p_now timestamptz
) returns void
language sql
security definer
set search_path = public
as $$
  insert into public.first_ai_onboarding_states (
    user_id,
    completed_at,
    result_opened_at,
    result_acknowledged_at,
    updated_at
  )
  values (p_user_id, p_now, p_now, p_now, p_now)
  on conflict (user_id) do update
  set
    completed_at = coalesce(public.first_ai_onboarding_states.completed_at, excluded.completed_at),
    result_opened_at = coalesce(public.first_ai_onboarding_states.result_opened_at, excluded.result_opened_at),
    result_acknowledged_at = coalesce(public.first_ai_onboarding_states.result_acknowledged_at, excluded.result_acknowledged_at),
    updated_at = case
      when public.first_ai_onboarding_states.completed_at is null then excluded.updated_at
      else public.first_ai_onboarding_states.updated_at
    end
  where public.first_ai_onboarding_states.dismissed_at is null;
$$;

revoke execute on function public.record_first_ai_onboarding_acknowledge_result(uuid, timestamptz) from public, anon, authenticated;
grant execute on function public.record_first_ai_onboarding_acknowledge_result(uuid, timestamptz) to service_role;

insert into public.first_ai_onboarding_states (user_id, completed_at, updated_at)
select p.id, now(), now()
from public.profiles p
where p.created_at <= now()
on conflict (user_id) do nothing;

alter table public.first_ai_onboarding_states enable row level security;

do $$
begin
  if not exists (
    select 1
    from pg_policies
    where schemaname = 'public'
      and tablename = 'first_ai_onboarding_states'
      and policyname = 'first_ai_onboarding_select_own'
  ) then
    create policy first_ai_onboarding_select_own
      on public.first_ai_onboarding_states
      for select
      using (auth.uid() = user_id);
  end if;
end $$;

do $$
begin
  if not exists (
    select 1
    from pg_trigger
    where tgname = 'update_first_ai_onboarding_states_updated_at'
  ) then
    create trigger update_first_ai_onboarding_states_updated_at
      before update on public.first_ai_onboarding_states
      for each row
      execute function public.update_updated_at_column();
  end if;
end $$;


-- ------------------------------------------------------------------
-- Source: supabase/sql/candidate_desired_salary_v1.sql
-- ------------------------------------------------------------------
alter table public.candidates
  add column if not exists desired_salary_text text,
  add column if not exists desired_salary_amount bigint,
  add column if not exists desired_salary_currency text,
  add column if not exists desired_salary_source text;

do $$
begin
  if not exists (
    select 1
    from pg_constraint
    where conname = 'candidates_desired_salary_amount_non_negative'
      and conrelid = 'public.candidates'::regclass
  ) then
    alter table public.candidates
      add constraint candidates_desired_salary_amount_non_negative
      check (desired_salary_amount is null or desired_salary_amount >= 0);
  end if;

  if not exists (
    select 1
    from pg_constraint
    where conname = 'candidates_desired_salary_amount_max'
      and conrelid = 'public.candidates'::regclass
  ) then
    alter table public.candidates
      add constraint candidates_desired_salary_amount_max
      check (desired_salary_amount is null or desired_salary_amount <= 999999999999999);
  end if;

  if not exists (
    select 1
    from pg_constraint
    where conname = 'candidates_desired_salary_text_length'
      and conrelid = 'public.candidates'::regclass
  ) then
    alter table public.candidates
      add constraint candidates_desired_salary_text_length
      check (desired_salary_text is null or char_length(desired_salary_text) <= 160);
  end if;

  if not exists (
    select 1
    from pg_constraint
    where conname = 'candidates_desired_salary_currency_length'
      and conrelid = 'public.candidates'::regclass
  ) then
    alter table public.candidates
      add constraint candidates_desired_salary_currency_length
      check (desired_salary_currency is null or char_length(desired_salary_currency) <= 12);
  end if;

  if not exists (
    select 1
    from pg_constraint
    where conname = 'candidates_desired_salary_source_check'
      and conrelid = 'public.candidates'::regclass
  ) then
    alter table public.candidates
      add constraint candidates_desired_salary_source_check
      check (desired_salary_source is null or desired_salary_source in ('hh', 'ai_parser', 'regex'));
  end if;

  if not exists (
    select 1
    from pg_constraint
    where conname = 'candidates_desired_salary_displayable'
      and conrelid = 'public.candidates'::regclass
  ) then
    alter table public.candidates
      add constraint candidates_desired_salary_displayable
      check (
        (
          desired_salary_text is null
          and desired_salary_amount is null
          and desired_salary_currency is null
          and desired_salary_source is null
        )
        or (nullif(btrim(desired_salary_text), '') is not null and desired_salary_source is not null)
      );
  end if;
end $$;

drop function if exists public.create_candidate_with_idempotency(
  text,
  text,
  uuid,
  uuid,
  text,
  uuid,
  text,
  text,
  text,
  text,
  timestamptz,
  text
);

create or replace function public.create_candidate_with_idempotency(
  p_key text,
  p_operation text,
  p_user_id uuid,
  p_company_id uuid,
  p_request_hash text,
  p_vacancy_id uuid,
  p_name text,
  p_position text,
  p_resume_text text,
  p_source text,
  p_applied_at timestamptz,
  p_mode text default 'enqueue',
  p_desired_salary_text text default null,
  p_desired_salary_amount bigint default null,
  p_desired_salary_currency text default null,
  p_desired_salary_source text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  inserted_count integer := 0;
  idem public.api_idempotency_keys;
  cand public.candidates;
  job public.jobs_ai;
  v_normalized_mode text := coalesce(p_mode, 'enqueue');
  v_response_status integer;
  v_response_body jsonb;
  v_desired_salary_text text := nullif(left(trim(coalesce(p_desired_salary_text, '')), 160), '');
  v_desired_salary_amount bigint := case
    when p_desired_salary_amount is not null
      and p_desired_salary_amount >= 0
      and p_desired_salary_amount <= 999999999999999
      then p_desired_salary_amount
    else null
  end;
  v_desired_salary_currency text := nullif(left(upper(trim(coalesce(p_desired_salary_currency, ''))), 12), '');
  v_desired_salary_source text := case
    when p_desired_salary_source in ('hh', 'ai_parser', 'regex') then p_desired_salary_source
    else null
  end;
begin
  if v_normalized_mode not in ('enqueue', 'skip_ai_analysis', 'subscription_inactive') then
    raise exception 'invalid candidate create mode: %', v_normalized_mode;
  end if;

  if v_desired_salary_text is null and v_desired_salary_amount is not null then
    v_desired_salary_text := left(
      trim(replace(replace(to_char(v_desired_salary_amount, 'FM999G999G999G999G999'), ',', ' '), '.', ' ') || coalesce(' ' || v_desired_salary_currency, '')),
      160
    );
  end if;

  if v_desired_salary_text is null or v_desired_salary_source is null then
    v_desired_salary_text := null;
    v_desired_salary_amount := null;
    v_desired_salary_currency := null;
    v_desired_salary_source := null;
  end if;

  insert into public.api_idempotency_keys (
    key,
    operation,
    user_id,
    company_id,
    request_hash,
    status
  ) values (
    p_key,
    p_operation,
    p_user_id,
    p_company_id,
    p_request_hash,
    'in_progress'
  )
  on conflict do nothing;

  get diagnostics inserted_count = row_count;

  if inserted_count = 0 then
    select *
    into idem
    from public.api_idempotency_keys
    where key = p_key
    for update;

    if not found then
      raise exception 'idempotency key lookup failed for key %', p_key;
    end if;

    if idem.operation <> p_operation
      or idem.user_id <> p_user_id
      or idem.company_id <> p_company_id
      or idem.request_hash <> p_request_hash then
      return jsonb_build_object(
        'responseStatus', 409,
        'responseBody', jsonb_build_object('error', 'IDEMPOTENCY_KEY_REUSED'),
        'candidateId', idem.candidate_id,
        'jobId', idem.job_id,
        'replayed', true
      );
    end if;

    if idem.status = 'completed'
      and idem.response_status is not null
      and idem.response_body is not null then
      return jsonb_build_object(
        'responseStatus', idem.response_status,
        'responseBody', idem.response_body,
        'candidateId', idem.candidate_id,
        'jobId', idem.job_id,
        'replayed', true
      );
    end if;

    return jsonb_build_object(
      'responseStatus', 409,
      'responseBody', jsonb_build_object('error', 'IDEMPOTENCY_REQUEST_IN_PROGRESS'),
      'candidateId', idem.candidate_id,
      'jobId', idem.job_id,
      'replayed', true
    );
  end if;

  insert into public.candidates (
    name,
    position,
    vacancy_id,
    created_by,
    resume_text,
    source,
    status,
    applied_at,
    desired_salary_text,
    desired_salary_amount,
    desired_salary_currency,
    desired_salary_source
  ) values (
    p_name,
    p_position,
    p_vacancy_id,
    p_user_id,
    p_resume_text,
    p_source,
    'new',
    p_applied_at,
    v_desired_salary_text,
    v_desired_salary_amount,
    v_desired_salary_currency,
    v_desired_salary_source
  )
  returning * into cand;

  if v_normalized_mode = 'enqueue' then
    select *
    into job
    from public.enqueue_ai_job_with_credit_reserve(
      p_company_id,
      cand.id,
      p_user_id,
      1
    );

    v_response_status := 200;
    v_response_body := jsonb_build_object(
      'candidateId', cand.id,
      'jobId', job.id
    );
  elsif v_normalized_mode = 'skip_ai_analysis' then
    v_response_status := 200;
    v_response_body := jsonb_build_object(
      'candidateId', cand.id,
      'jobId', null
    );
  else
    v_response_status := 402;
    v_response_body := jsonb_build_object(
      'error', 'SUBSCRIPTION_INACTIVE',
      'candidateId', cand.id
    );
  end if;

  update public.api_idempotency_keys
    set status = 'completed',
        response_status = v_response_status,
        response_body = v_response_body,
        candidate_id = cand.id,
        job_id = job.id,
        updated_at = now()
  where key = p_key;

  return jsonb_build_object(
    'responseStatus', v_response_status,
    'responseBody', v_response_body,
    'candidateId', cand.id,
    'jobId', job.id,
    'replayed', false
  );
exception
  when others then
    delete from public.api_idempotency_keys
    where key = p_key
      and status = 'in_progress'
      and response_status is null;
    raise;
end;
$$;

