  v_has_plan := found;

  if not v_has_plan or v_company_plan.current_plan <> 'enterprise' then
    raise exception 'COMPANY_PLAN_ENTERPRISE_REQUIRED';
  end if;

  update public.enterprise_agreements ea
    set status = 'ended',
